(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c47"]=[{"id":"00010427","register_sub_id":"101","register_pk":"199387","name":"旧園田家住宅スタジオ","kana":"きゅうそのだけじゅうたくすたじお","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都目黒区緑が丘2-2374-5","lat":35.610938,"lng":139.671617,"geo_status":"db","era":"昭和30","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造2階建、金属板葺、建築面積55㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"13 － 0357","desc":"音楽家の自宅兼スタジオ。比較的簡素な資材を用いた小規模建築であるが、グランドピアノ二台を置いた音楽室を上部吹抜とし、暖炉付の居間では天井を低く抑えつつ障子越しに採光を図るなど、豊かな内部空間を創出する。吉村順三の作風を示す木造モダニズム建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010427"},{"id":"00011485","register_sub_id":"101","register_pk":"210451","name":"旧高橋家住宅主屋","kana":"きゅうたかはしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都西多摩郡檜原村2032","lat":35.71323889,"lng":139.08567,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積185㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"13-0379","desc":"山間地の旧街道沿いに南面して建つ。入母屋造茅葺（鉄板仮葺）の民家。正面はせがい造とし、式台玄関を備える。内法の高い内部空間で、座敷や神棚など随所に良質な造りが見られる。外観も高い建ちを見せ、地域の歴史を伝える大型民家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011485"},{"id":"00015299","register_sub_id":"101","register_pk":"532423","name":"旧辻󠄀陶房主屋兼作業場","kana":"きゅうつじとうぼうおもやけんさぎょうば","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都多摩市連光寺三丁目28-9","lat":35.64264722,"lng":139.45903611,"geo_status":"db","era":"昭和30年／昭和45年増築","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"13 - 0520","desc":"多摩川南岸の丘陵地に位置する陶芸家辻清明の主屋兼作業場。平屋建切妻造平入桟瓦葺で、南東を土間の作業場、西に座敷と台所を配し、西端に洋室を突出する。鎧庇付の太い出格子構えとした民芸調の外観で大黒柱に古材を用いるなど辻の趣向を反映したつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015299"},{"id":"00015300","register_sub_id":"101","register_pk":"532424","name":"旧辻󠄀陶房登り窯","kana":"きゅうつじとうぼうのぼりがま","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都多摩市連光寺三丁目28-9","lat":35.64263333,"lng":139.45915,"geo_status":"db","era":"昭和30年頃／昭和43年・同48年増築","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"連房式登り窯、建築面積24㎡","structure_material":"連房式登り窯","registered":"2025.03.13(令和7.03.13)","register_no":"13 - 0521","desc":"主屋兼作業場東隣に位置し、北が高くなる高低差一・三メートルの傾斜地に築造した連房式登り窯。幅二・四メートル、全長九メートルで、直線上に六つの燃焼室を並べ、南に主焚口を開け、北に煉瓦造の煙突を立てる。主屋兼作業場とともに窯元の構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015300"},{"id":"00012713","register_sub_id":"101","register_pk":"367616","name":"旧中村研一邸主屋","kana":"きゅうなかむらけんいちていしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都小金井市中町一丁目416","lat":35.691915,"lng":139.51839583,"geo_status":"db","era":"昭和34年／平成元年・同18年改修","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"木造2階一部地下1階建、瓦葺、建築面積87㎡","structure_material":"木造2階一部地下1階建","registered":"2019.03.29(平成31.03.29)","register_no":"13 － 417","desc":"武蔵野段丘崖線の南斜面にある洋画家・中村研一の旧宅。主屋は敷地中央に建つ木造二階建で、切妻造桟瓦葺の大屋根をかけ、北側に玄関や便所、南側に客間兼居間と食堂を一空間で設ける。佐藤秀三の設計で、伝統木造に現代的な空間構成を取り入れた和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012713"},{"id":"00012714","register_sub_id":"101","register_pk":"367617","name":"旧中村研一邸茶室（花侵庵）","kana":"きゅうなかむらけんいちていちゃしつ（かしんあん）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都小金井市中町一丁目416-1","lat":35.691915,"lng":139.51839583,"geo_status":"db","era":"昭和35年／平成元年改修","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"13 － 418","desc":"主屋の西側に並んで建つ。木造平屋建、切妻造桟瓦葺で、東に四畳半の茶室、西に水屋と厠を配し、茶室は南面に貴人口、北面に床、東面に付書院風の出窓を設ける。主要な部材に旧宅の古材を用いる。素材の選択と構成に手腕をみせる佐藤秀三の代表作の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012714"},{"id":"00006808","register_sub_id":"101","register_pk":"107790","name":"旧丹羽家住宅蔵","kana":"きゅうにわけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都豊島区駒込3-498-8","lat":35.73797703,"lng":139.74253189,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建、瓦葺、建築面積25㎡","structure_material":"鉄筋コンクリート造2階地下1階建","registered":"2008.03.07(平成20.03.07)","register_no":"13 － 0227","desc":"敷地の北東隅に南北棟で建つ。正面４．５ｍ奥行５．５ｍ、鉄筋コンクリート造、地上２階、地下１階、切妻造妻入桟瓦葺である。外壁は洗出し仕上げで、水切りを２段付け、軒蛇腹も丁寧に作る。両妻面の窓庇は銅板葺とする。近代工法を用いた伝統的意匠の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006808"},{"id":"00009910","register_sub_id":"101","register_pk":"196057","name":"旧弘田家住宅主屋","kana":"きゅうひろたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区弥生2-3-103他","lat":35.7174481,"lng":139.76323594,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積129㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0325","desc":"弥生坂に通じる小路に面する。Ｌ字形平面を持ち、玄関左手に洋室、右手には台所や食堂を置き、最奥にピアノのある音楽室を配する。外壁をリシン掻落としとして窓に鎧戸を開くなど、スパニッシュスタイルでまとめる。洋行帰りの作曲家の嗜好を反映した住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009910"},{"id":"00009911","register_sub_id":"101","register_pk":"196058","name":"旧弘田家住宅門柱及び塀","kana":"きゅうひろたけじゅうたくもんちゅうおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区弥生2-3-103他","lat":35.71748793,"lng":139.76339179,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"門柱 コンクリート造 塀 コンクリート造、瓦葺、総延長14m、潜付","structure_material":"門柱 コンクリート造 塀 コンクリート造","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0326","desc":"敷地の東辺を区画する門柱と塀。門柱にはフルーティングが施される。塀の屈曲部は円弧を描いて滑らかに繋がり、潜の上辺も円弧を描く。塀の上部には赤色のスペイン瓦を葺き、モルタルにリシンを吹き付けることで表情を作り、スパニッシュスタイルでまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009911"},{"id":"00014763","register_sub_id":"101","register_pk":"519021","name":"旧前田家（キンデー）住宅釜屋形","kana":"きゅうまえだけ（きんでー）じゅうたくかまやかた","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都新島村本村一丁目318-2","lat":34.37678333,"lng":139.25683611,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"石造平屋建、石葺、建築面積8.4㎡","structure_material":"石造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"13 - 0508","desc":"役場前の屋敷に位置する釜屋形。コーガ石を用いた石造切妻造妻入石葺で、内部は南北二室とし、南は土間で石のヘッツイを備え、北は風呂場とする。上部は母屋を直接石積の頂部に架ける。独立した釜屋形の形式を良く残し、新島の伝統的民家の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014763"},{"id":"00012508","register_sub_id":"101","register_pk":"367803","name":"旧武者小路実篤邸主屋","kana":"きゅうむしゃこうじさねあつていしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都調布市若葉町一丁目23-20他","lat":35.658047,"lng":139.581284,"geo_status":"geocoded","era":"昭和30年","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋建地下室付、金属板葺、建築面積195㎡","structure_material":"木造平屋建地下室付","registered":"2018.11.02(平成30.11.02)","register_no":"13 － 0415","desc":"文豪･武者小路実篤が晩年を過ごした自邸。武蔵野段丘崖線上の敷地中央に建つ木造平屋建、切妻造鉄板葺で、山側の北面に玄関、谷側の南面に居室を設ける。外観はモルタル大壁で重厚に仕上げつつ、内部は新興数寄屋風で瀟洒にまとめる。戦後和風住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012508"},{"id":"00012296","register_sub_id":"101","register_pk":"531620","name":"旧山口萬吉邸主屋","kana":"きゅうやまぐちまんきちていしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区九段北一丁目32-4","lat":35.69618611,"lng":139.7481,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造3階建地下1階、建築面積280㎡","structure_material":"鉄筋コンクリート造3階建地下1階","registered":"2018.05.10(平成30.05.10)","register_no":"13-402","desc":"東京九段の高台にある邸宅で、主屋は敷地北寄りに南面して建つ。木子七郎が意匠、内藤多仲が構造を担当し、壁式構造の量感ある躯体を、当時流行のスパニッシュ風意匠で軽快にまとめる。壁式構造の内藤自邸（大正15年）も木子と内藤が共同設計している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012296"},{"id":"00012297","register_sub_id":"101","register_pk":"531621","name":"旧山口萬吉邸門及び塀","kana":"きゅうやまぐちまんきちていもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区九段北一丁目32-4","lat":35.69625556,"lng":139.74801667,"geo_status":"db","era":"昭和8年頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"表門 鉄筋コンクリート造、瓦葺、間口4.1m 塀 鉄筋コンクリート造、総延長61m、車庫付","structure_material":"表門 鉄筋コンクリート造","registered":"2018.05.10(平成30.05.10)","register_no":"13-403","desc":"街路に面した敷地の北面と西面を区切る塀と北面西端に開いた切妻造の門。西面北端には陸屋根の車庫を置く。鉄筋コンクリート造の重厚な躯体をスペイン瓦をアクセントにして柔和に整える。主屋と調和した構造・意匠で一体感のある屋敷構えを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012297"},{"id":"00010270","register_sub_id":"101","register_pk":"199043","name":"旧ヤマジュウ田村家住宅主屋","kana":"きゅうやまじゅうたむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都福生市大字福生字奈賀1158","lat":35.741495,"lng":139.322117,"geo_status":"db","era":"明治35年／大正5年改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積268㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"13-0350","desc":"敷地中ほどに南面して建つ。桁行一一間規模の入母屋造で周囲に下屋を設ける。右土間の六間取系平面で土間の一部に板床を張出し、鍵座敷形の主座敷にトコを構える。引分けの大戸や三方に廻す廊下など、形式の発達と意匠の洗練が認められる近代の大型民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010270"},{"id":"00010271","register_sub_id":"101","register_pk":"199044","name":"旧ヤマジュウ田村家住宅西土蔵","kana":"きゅうやまじゅうたむらけじゅうたくにしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都福生市大字福生字奈賀1158","lat":35.741651,"lng":139.322022,"geo_status":"db","era":"明治37年","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"13-0351","desc":"主屋の北側後方に東土蔵と南北棟で並び建つ。土蔵造二階建、桁行六・四メートル梁間四・三メートル、置屋根式の鉄板葺で、南面の戸口に下屋を設ける。外壁は漆喰塗で、両側面及び背面の腰は簓子下見板張とする。主屋及び東土蔵とともに屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010271"},{"id":"00010272","register_sub_id":"101","register_pk":"199045","name":"旧ヤマジュウ田村家住宅東土蔵","kana":"きゅうやまじゅうたむらけじゅうたくひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都福生市大字福生字奈賀1158","lat":35.741672,"lng":139.322104,"geo_status":"db","era":"明治44年","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"13-0352","desc":"主屋の北側後方に西土蔵と並び建つ。土蔵造二階建、桁行六・二メートル梁間四・三メートル、置屋根式の桟瓦葺で、南面の戸口に下屋を設ける。東側面及び背面の腰は簓子下見板張。主屋や西土蔵と同じ棟梁が手がけ、敷地内に統一された景観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010272"},{"id":"00011482","register_sub_id":"101","register_pk":"210448","name":"旧吉岡家住宅蔵","kana":"きゅうよしおかけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都東大和市清水三丁目779-4","lat":35.75438,"lng":139.44241389,"geo_status":"db","era":"明治17年頃／昭和前期改修","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造２階建、鉄板葺、建築面積33㎡","structure_material":"木造２階建","registered":"2017.05.02(平成29.05.02)","register_no":"13-0376","desc":"主屋の南西に東面して建つ。桁行七・三メートル、梁間四・五メートルの切妻造鉄板葺、木造二階建。屋根は置屋根、外壁はモルタル洗い出しで石造風に仕上げる。出入口と窓の開口部には観音開きの防火戸が納まり、伝統的要素を備えた落ち着いた外観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011482"},{"id":"00011481","register_sub_id":"101","register_pk":"210447","name":"旧吉岡家住宅主屋兼アトリエ","kana":"きゅうよしおかけじゅうたくしゅおくけんあとりえ","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都東大和市清水三丁目779-1他","lat":35.75454694,"lng":139.44256,"geo_status":"db","era":"明治中期／昭和37年増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積208㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"13-0375","desc":"四間取の平面形式をもとに、昭和に増改築が施された大型農家。木造平屋一部二階建、切妻造桟瓦葺。大黒柱や差鴨居に大材を用い豪壮な造りを見せる一方、座敷欄間の組子は緻密な意匠で仕上げる。土間部は当初の架構を活かしつつアトリエとして改修された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011481"},{"id":"00011484","register_sub_id":"101","register_pk":"210450","name":"旧吉岡家住宅中門","kana":"きゅうよしおかけじゅうたくちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都東大和市清水三丁目779-4","lat":35.75447389,"lng":139.44243389,"geo_status":"db","era":"昭和37年","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"木造、鉄板葺、間口1.8m","structure_material":"木造","registered":"2017.05.02(平成29.05.02)","register_no":"13-0378","desc":"主屋西側の坪庭と前庭を限る庭塀に開く間口一・八メートルの腕木門。屋根は若干起りのある切妻造、鉄板葺で、棟は瓦葺。もとは現在の長屋門の位置に建っており、長屋門建設時に現在地に移設された。坪庭と一体となって敷地内景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011484"},{"id":"00011483","register_sub_id":"101","register_pk":"210449","name":"旧吉岡家住宅長屋門","kana":"きゅうよしおかけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都東大和市清水三丁目779-5","lat":35.75435389,"lng":139.44284806,"geo_status":"db","era":"昭和37年","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"13-0377","desc":"主屋南東に街路に面して建つ。木造平屋建、寄棟造桟瓦葺、軒をせがい造とする。中央間を門口とし、北側に潜戸を開く。外壁は真壁漆喰塗で正面の腰壁を板張りとする。昭和三七年に他所の長屋門の部材を用いて現在地に建築したもので、屋敷構えに風格を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011483"},{"id":"00014463","register_sub_id":"101","register_pk":"512447","name":"旧吉川英治邸（草思堂）主屋","kana":"きゅうよしかわえいじてい（そうしどう）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都青梅市柚木町一丁目101-1","lat":35.79610278,"lng":139.21327778,"geo_status":"db","era":"明治中期／昭和23年頃改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、銅板葺、建築面積240㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"13 - 0479","desc":"大型養蚕民家を戦後に作家吉川英治の設計で改修した住宅。切妻造で煙出しを三つ備え明治期養蚕民家の特徴を示す。土間に設けた和洋折衷応接室は編集者等の待合で、吉川のこだわりの設計箇所。１０畳２室の続き間座敷は庭に開いて広壮で、執筆と寝室に用いた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014463"},{"id":"00014465","register_sub_id":"101","register_pk":"512449","name":"旧吉川英治邸（草思堂）土蔵","kana":"きゅうよしかわえいじてい（そうしどう）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都青梅市柚木町一丁目101-1","lat":35.79596944,"lng":139.21345278,"geo_status":"db","era":"弘化4年(1847)","year":1847,"year_source":"db","year_min":1847,"year_max":1847,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"13 - 0481","desc":"旧吉野村の旧家で養蚕農家の土蔵。切妻造平入、桟瓦葺置屋根の土蔵造二階建で頂部に鉢巻付。戸前に奥行一間の庇を架け、掛子塗の観音扉を建てる。内部は各階板敷、内壁も板張とし、小屋組は束立。棟札に「風門之倉庫」と記し、屋敷構え南東部を構成する巽蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014465"},{"id":"00014466","register_sub_id":"101","register_pk":"512450","name":"旧吉川英治邸（草思堂）長屋門","kana":"きゅうよしかわえいじてい（そうしどう）ながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都青梅市柚木町一丁目101-1","lat":35.7959,"lng":139.21336667,"geo_status":"db","era":"江戸時代末期／昭和58年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造2階建、銅板葺、建築面積63㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"13 - 0482","desc":"旧吉野村の旧家で養蚕農家の長屋門。切妻造銅板葺で元は杉皮葺。正面東側に出格子、つしに窓を設ける。西袖部屋は土間、東袖部屋は板敷で戦時中は疎開者の住居、戦後は吉川英治が書庫や物置として使用した。養蚕農家の表構えを構成し、戦時中の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014466"},{"id":"00014464","register_sub_id":"101","register_pk":"512448","name":"旧吉川英治邸（草思堂）洋館","kana":"きゅうよしかわえいじてい（そうしどう）ようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都青梅市柚木町一丁目101-1","lat":35.79618889,"lng":139.21314444,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"13 - 0480","desc":"作家吉川英治が書斎とした旧家の座敷奥離れの洋館。寄棟造桟瓦葺で軒にブラケットを巡らす。正面に瀬戸本業タイル敷のテラスを配し、上下窓や床構え風アルコーブを設けた書斎を中心に板間と納戸を付設する。基礎に大谷石を用いる等、各地の建築資材を集める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014464"},{"id":"00010425","register_sub_id":"101","register_pk":"199385","name":"栗原家住宅稲荷社及び石鳥居","kana":"くりはらけじゅうたくいなりしゃおよびいしどりい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都新宿区中井2-1981-1","lat":35.717288,"lng":139.686553,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"稲荷社 木造平屋建、銅板葺、建築面積0.2㎡、覆屋付 石鳥居 石造、高さ1.9m","structure_material":"稲荷社 木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"13 － 0355","desc":"主屋の南西側に祀られる屋敷社。稲荷社は一間社流造、銅板葺で、正面に千鳥破風を飾る。総ケヤキの素木造で、身舎正面部や庇、脇障子に龍や鶴などの優秀な彫刻を飾る。北東側に位置する石鳥居は、花崗岩製の小型の石造鳥居。屋敷構えに趣を添える小社である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010425"},{"id":"00010424","register_sub_id":"101","register_pk":"199384","name":"栗原家住宅蔵","kana":"くりはらけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都新宿区中井2-1981","lat":35.717391,"lng":139.686533,"geo_status":"db","era":"昭和20頃","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積26㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"13 － 0354","desc":"敷地西側に南北棟で建つ質屋経営時の物品収納蔵。鉄筋コンクリート造二階建、切妻造桟瓦葺で主屋西側の蔵前廊下に接続する。外壁はモルタル塗で石造風に目地を切り、鉢巻を廻らし、妻側に庇付の小窓を穿つ。生業の変遷を伝える、堅牢な鉄筋コンクリート造の蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010424"},{"id":"00010423","register_sub_id":"101","register_pk":"199383","name":"栗原家住宅主屋","kana":"くりはらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都新宿区中井2-1981","lat":35.717418,"lng":139.686665,"geo_status":"db","era":"昭和12／平成25改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積162㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"13 － 0353","desc":"敷地北寄りに東面する木造二階建で、大屋根と玄関等を入母屋造桟瓦葺とする。外壁は玄関脇の洋間の応接室をスクラッチタイル貼とするほかは下見板張及び漆喰塗とする。居室部の平面を中廊下式として南に縁を通すなど、昭和初期の中規模住宅の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010423"},{"id":"00010426","register_sub_id":"101","register_pk":"199386","name":"栗原家住宅門柱及び塀","kana":"くりはらけじゅうたくもんちゅうおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都新宿区中井2-1981-1","lat":35.7172492,"lng":139.6868601,"geo_status":"db","era":"昭和12頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"正門 石造、間口2.5m 裏門 石造、間口2.2m 塀 石造、総延長51m 擁壁 石造、総延長52m","structure_material":"正門 石造","registered":"2015.03.26(平成27.03.26)","register_no":"13 － 0356","desc":"敷地東面中央の客用入口及びその北寄りの勝手口に建つ門柱と、東、南、西の三面を区画する大谷石積の塀である。敷地が斜面地であるため、高低差がある境界部は擁壁を兼ねた構造とする。門柱はいずれも花崗岩製で、特に客用入口は階段上に立ち、風格を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010426"},{"id":"00007883","register_sub_id":"101","register_pk":"108863","name":"幻戯山房（旧角川家住宅主屋）","kana":"げんぎさんぼう（きゅうかどかわけじゅうたくしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都杉並区荻窪3-728","lat":35.69882287,"lng":139.62446068,"geo_status":"db","era":"昭和30／昭和48・平成20改修","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積196㎡","structure_material":"木造2階一部平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"13-0254","desc":"敷地の北辺に沿って建つ。木造２階一部平屋建、東西棟の入母屋造桟瓦葺、建築面積１９６㎡。開口とする隅柱を省略し、主な開口部の建具をすべて引込み戸とすることにより、開放的な内部空間と、繊細な外観をつくる。近代数寄屋建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007883"},{"id":"00008418","register_sub_id":"101","register_pk":"134814","name":"小池家住宅主屋","kana":"こいけけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都品川区北品川5-740-10","lat":35.62074226,"lng":139.7349103,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積205㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"13 － 0267","desc":"御殿山丘陵の住宅地に所在し、敷地北半に建つ。腰折れ屋根の切妻造桟瓦葺で、妻面をハーフティンバー風とし、正面一階外壁に鉄平石を貼る。柱や梁、破風などは名栗仕上げ。玄関脇に洋間を設け、中廊下式平面になり、南面にテラス等を設ける。郊外型住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008418"},{"id":"00000393","register_sub_id":"101","register_pk":"101383","name":"古宇田家住宅","kana":"こうだけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都杉並区南荻窪三丁目14","lat":35.70224375,"lng":139.61081417,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建，スレート葺，建築面積89㎡","structure_material":"木造2階建","registered":"1997.12.12(平成9.12.12)","register_no":"13 － 0008","desc":"震災後この一帯では，和洋の邸宅が建ち並ぶ町並みが形成された。古宇田家住宅もその一つで，広い屋敷地のなかに切妻の大屋根と持ち送りのある２階開口部など独特の外観になる洋館として知られている。東京西郊における昭和初期の洋館の好例の一つでもある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000393"},{"id":"00001373","register_sub_id":"101","register_pk":"102363","name":"国際基督教大学泰山荘表門","kana":"こくさいきりすときょうだいがくたいざんそうおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都三鷹市大沢3-10-2","lat":35.68578228,"lng":139.52763155,"geo_status":"db","era":"昭和11頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造、茅葺、高さ5.0m、幅7.1m","structure_material":"木造","registered":"1999.10.14(平成11.10.14)","register_no":"13 － 0062","desc":"「泰山荘」敷地の北端からやや南に下った地点に建つ間口３．３５ｍ，高さ５ｍの茅葺の薬医門。「泰山荘」の建設を指揮した茶匠亀山宗月の好みが表れた雅趣ある門で，江戸城幸橋御門の桝形土壇から発掘された古材を用いている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001373"},{"id":"00001371","register_sub_id":"101","register_pk":"102361","name":"国際基督教大学泰山荘蔵","kana":"こくさいきりすときょうだいがくたいざんそうくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都三鷹市大沢3-10-2","lat":35.6855248,"lng":139.52806475,"geo_status":"db","era":"昭和11頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積55㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"13 － 0060","desc":"書院の東方に建つ南北棟，瓦葺切妻屋根，妻入の蔵で，北妻面に下屋を差し出して蔵前とする。鉄筋コンクリート造で土蔵風の外観をつくっているが，蔵前部を除いて庫室本体部を高床式としている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001371"},{"id":"00001368","register_sub_id":"101","register_pk":"102358","name":"国際基督教大学泰山荘高風居","kana":"こくさいきりすときょうだいがくたいざんそうこうふうきょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都三鷹市大沢3-10-2","lat":35.684868,"lng":139.52781772,"geo_status":"db","era":"明治19・大正14/昭和11移築","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、茅葺、建築面積39㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"13 － 0057","desc":"実業家山田敬亮の別荘「泰山荘」の核となる建築。松浦武四郎邸の「一畳敷」書斎に，徳川頼倫が６畳茶室などを付け加えた茅葺草庵風建物を移築したもの。「一畳敷」は，松浦武四郎が全国の社寺の古材を譲り受けて組み上げた特異な空間として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001368"},{"id":"00001372","register_sub_id":"101","register_pk":"102362","name":"国際基督教大学泰山荘車庫","kana":"こくさいきりすときょうだいがくたいざんそうしゃこ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都三鷹市大沢3-10-2","lat":35.68554765,"lng":139.52732813,"geo_status":"db","era":"昭和11頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積36㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"13 － 0061","desc":"国際基督教大学の一画に取り込まれている「泰山荘」の表門を入って右手のやや奥まった位置に建つ，木造平屋建，下見板貼，寄棟屋根の建物で，南面に３枚扉を付ける。郊外住宅地における自動車普及の時代状況を物語る遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001372"},{"id":"00001369","register_sub_id":"101","register_pk":"102359","name":"国際基督教大学泰山荘書院","kana":"こくさいきりすときょうだいがくたいざんそうしょいん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都三鷹市大沢3-10-2","lat":35.68540276,"lng":139.52796596,"geo_status":"db","era":"昭和11頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積77㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"13 － 0058","desc":"昭和４１年に焼失した主屋（日野の農家を移築）の東南方に位置した新築の座敷棟。６畳間と，上段付き８畳間の２室構成に，濡れ縁付きの畳縁を回し，東面に板敷縁をつけた上品な造りの座敷棟で，大学の各種行事に利用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001369"},{"id":"00001370","register_sub_id":"101","register_pk":"102360","name":"国際基督教大学泰山荘待合","kana":"こくさいきりすときょうだいがくたいざんそうまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都三鷹市大沢3-10-2","lat":35.68532279,"lng":139.527267,"geo_status":"db","era":"江戸末期／昭和11頃移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺、建築面積43㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"13 － 0059","desc":"４畳半の茶室，４畳半の間，３畳の水屋，７畳半分の土間などから成る茅葺の農家風の建物で，もと備前池田家上屋敷の「池亭」を移築したと伝える。「泰山荘」敷地の西端に位置し，本席としての高風居の待合的施設になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001370"},{"id":"00014764","register_sub_id":"101","register_pk":"519022","name":"小久保家住宅主屋","kana":"こくぼけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都新島村本村四丁目526","lat":34.37411667,"lng":139.25716944,"geo_status":"db","era":"大正9年頃","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、石葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"13 - 0509","desc":"本村中心部に位置する漁家の主屋。敷地北寄りに南面して建つ寄棟造石葺で棟中央に煙出を設ける。側廻りをコーガ石積、東半南を土間、北を板間、西半は田の字に部屋を配し、座敷に床と仏壇を備える。瓦状に加工した石葺など新島の伝統的民家の特徴をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014764"},{"id":"00011891","register_sub_id":"101","register_pk":"354917","name":"五島美術館古経楼","kana":"ごとうびじゅつかんこきょうろう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都世田谷区上野毛三丁目110-7","lat":35.61191,"lng":139.635191,"geo_status":"db","era":"大正11年／昭和15年増改築、平成25年改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積128㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"13-388","desc":"政治家田健次郎が東宮行啓のため作った茶室は、玄関、寄付と次の間を介した広間と八畳からなる。広間は天井を折上げ、広縁には付書院を設け、格式を高めた近代の書院建築。五島慶太による増築部は、四畳台目で、高台寺旧小方丈茶室を写した近代茶室の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011891"},{"id":"00011890","register_sub_id":"101","register_pk":"354916","name":"五島美術館冨士見亭","kana":"ごとうびじゅつかんふじみてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都世田谷区上野毛三丁目110-7","lat":35.611709,"lng":139.6353,"geo_status":"db","era":"昭和32年／平成25年改修","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"13-387","desc":"五島慶太の最晩年に作られた茶室。土間と畳敷を併用し、座礼のみならず、可動式の客卓を用いて立礼式ともなる構え。西大寺旧山門の古材を床柱や亭主座脇の柱に用い、南面を大きく開放し富士山を眺める創意など、茶人としての五島慶太の趣向が随所に見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011890"},{"id":"00016653","register_sub_id":"101","register_pk":"579137","name":"小堀家住宅主屋","kana":"こぼりけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都世田谷区深沢八丁目108-7","lat":35.625751,"lng":139.644599,"geo_status":"db","era":"大正13年／昭和34年移築","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、銅板葺、建築面積128㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"13 - 0532","desc":"桜新町駅南方の開発住宅地に位置する日本画家小堀鞆音の旧宅。二階建入母屋造妻入銅板葺で西面に下屋を付し玄関とする。一階は中廊下の南に座敷や居間、北に水回りを配し、二階は五室で南東は元アトリエ。住宅地の中で建ちの高い入母屋の屋根が目を惹く主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016653"},{"id":"00009438","register_sub_id":"101","register_pk":"194231","name":"小宮家住宅主屋","kana":"こみやけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都西東京市ひばりが丘1-1568-3","lat":35.7499678,"lng":139.54091451,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積172㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"13 － 0293","desc":"市街地交差点に建つ、桟瓦葺平屋建の住宅建築。居間は庭側にテラスを配し、モダンなタイル張りの暖炉、作り付けの木製家具をもつ洋風意匠である。清楚な中にも特有のデザインを随所に施す、大正から昭和戦前期にかけての文化人による居間中心形住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009438"},{"id":"00003952","register_sub_id":"101","register_pk":"104942","name":"坂間家住宅主屋","kana":"さかまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都世田谷区下馬6-77-8","lat":35.62861405,"lng":139.68051506,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造3階建、瓦葺、建築面積134㎡","structure_material":"木造3階建","registered":"2004.03.02(平成16.03.02)","register_no":"13 － 0173","desc":"木造郊外住宅の一つ。東面する３階建，半切妻造，妻入，桟瓦葺の主体部を中心に，北面に２階建下屋，南面に平屋を付属する。内部は和洋両室を備えた折衷式だが，外観はモルタル壁に縦長の上げ下げ窓を並べ純洋風にまとめる。急勾配の赤瓦屋根が印象的な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003952"},{"id":"00007979","register_sub_id":"101","register_pk":"128811","name":"佐々木家住宅主屋","kana":"ささきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都練馬区小竹町1-36-11","lat":35.7382651,"lng":139.6762988,"geo_status":"db","era":"昭和9／昭和10改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"13-0257","desc":"西と南に接道した敷地に西を正面に建つ。木造平屋建、東西棟の寄棟造桟瓦葺。玄関から中廊下が延び、北側に水まわり等、南に洋間や、縁を介した客間と居間を並べる。押入の設置や部屋の雁行配置で部屋の独立性を高める。同潤会木造分譲住宅の姿をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007979"},{"id":"00002364","register_sub_id":"101","register_pk":"103354","name":"島薗家住宅主屋","kana":"しまぞのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区千駄木三丁目635-7","lat":35.72617,"lng":139.761002,"geo_status":"db","era":"昭和7／昭和16増築","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積145㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"13 － 0106","desc":"団子坂上北方の住宅分譲地の一画に位置する。東京帝大医学部教授の住宅で，創建当初の陸屋根造平屋建に２階を増築。１階の水平軒に陸屋根造の面影を残しつつ，小アーチの連続装飾帯など増築時の意匠で全体をまとめる。設計は増築とも矢部又吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002364"},{"id":"00005932","register_sub_id":"101","register_pk":"106917","name":"志村家住宅門及び石垣","kana":"しむらけじゅうたくもんおよびいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都世田谷区成城三丁目242-3他","lat":35.63738434,"lng":139.5956915,"geo_status":"db","era":"昭和14頃","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"門 コンクリート造、間口6.7m、石垣 石造、延長57m","structure_material":"門 コンクリート造","registered":"2006.11.29(平成18.11.29)","register_no":"13 － 0213","desc":"敷地北辺西寄りに開くコンクリート造の門柱は，大谷石の整層積とし，袖塀は大谷石基礎でモルタル塗とする。東にアーチ開口の脇門を設ける。門の東へ延びる石垣は敷地北辺から東辺へ巡る。基礎石に大谷石２石と笠石を積み，上部を生垣として緑樹景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005932"},{"id":"00012715","register_sub_id":"101","register_pk":"367618","name":"下田家住宅主屋","kana":"しもだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都西東京市田無町二丁目627","lat":35.72834278,"lng":139.54034083,"geo_status":"db","era":"江戸末期／明治22年・昭和41年・同52年・同61年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、銅板葺、建築面積209㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"13 － 419","desc":"西武田無駅近傍にある旧田無村の名主宅。主屋は敷地後方に東面して建つ。入母屋造銅板葺で、南に土間、北に前後二列三室を配し、前列中央室の前に入母屋造の式台を突出し、後列上手に座敷を設ける。市街化が著しい東京近郊の農村景観を伝える希少な民家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012715"},{"id":"00012716","register_sub_id":"101","register_pk":"367619","name":"下田家住宅文庫蔵","kana":"しもだけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都西東京市田無町二丁目627","lat":35.72834278,"lng":139.54034083,"geo_status":"db","era":"明治前期／大正12年頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"13 － 420","desc":"主屋背面の北端に接続して建つ。土蔵造二階建、切妻造桟瓦葺妻入で、南面に扉口を設ける。外壁は石造風のモルタル洗出し仕上、内部は上下階とも板敷で、二階中央部に荷揚げ用の開口を設ける。小屋組は登梁とする。上層農家の伝統的な屋敷構えを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012716"},{"id":"00009439","register_sub_id":"101","register_pk":"194232","name":"蛇の湯温泉たから荘","kana":"じゃのゆおんせんたからそう","category":"住宅","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都西多摩郡檜原村字数馬2465-1","lat":35.72621546,"lng":139.04980339,"geo_status":"db","era":"江戸後期／大正頃・昭和中期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"13 － 0294","desc":"山間地の古道に面して北面して建つ。屋根は表面に檜皮を葺く入母屋造茅葺であり、東妻側は富士型二重兜造と呼ばれる特徴ある形態をもつ。小屋組や室内の改変から地域における養蚕業の変遷がうかがえるなど、地域の歴史を伝える希少な大型民家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009439"},{"id":"00003199","register_sub_id":"101","register_pk":"104189","name":"松風荘主屋","kana":"しょうふうそうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都大田区南千束2-25-6","lat":35.60134846,"lng":139.688828,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺一部銅板葺、建築面積143㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"13 － 0143","desc":"洗足池西方の台地上に建つ茶室を備えた住宅建築。軒高を押さえた外観で，比較的小規模な部屋を配す一方で座敷飾を大きく取り，土庇や幅１間の広い板縁を回すなど，特徴ある平面を持つ。檜を主材としながら要所に銘木を用い，時代を表した数寄屋風意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003199"},{"id":"00003200","register_sub_id":"101","register_pk":"104190","name":"松風荘待合","kana":"しょうふうそうまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都大田区南千束2-25-6","lat":35.601234,"lng":139.688599,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺一部銅板葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"13 － 0144","desc":"門を入って左手奥に独立して建つ。北に主屋付属の３畳台目茶室があり，茶会の際の外待合となる。丸炉を備えた寄付３畳と不整形の土間，その裏に雪隠を付属する。小規模ながら杉丸太による本格的な数寄屋普請になり，複雑な屋根を掛け変化に富んだ外観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003200"},{"id":"00003201","register_sub_id":"101","register_pk":"104191","name":"松風荘門","kana":"しょうふうそうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都大田区南千束2-25-6","lat":35.6011849,"lng":139.68881635,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、銅板葺、間口1.7m","structure_material":"木造","registered":"2003.03.18(平成15.03.18)","register_no":"13 － 0145","desc":"敷地南辺ほぼ中央に南面して建つ。親柱背後に控えを立て，銅板葺で勾配の緩い入母屋屋根を架ける。戸口に太い鋲で板を密に打ち格子窓を開けた独特な意匠の扉を構え，まぐさ上に全体が彫刻化した蟇股を置く。簡素だが一部に法隆寺古材を使うなど，特徴ある門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003201"},{"id":"00002759","register_sub_id":"101","register_pk":"103749","name":"昭和のくらし博物館（旧小泉家住宅主屋）","kana":"しょうわのくらしはくぶつかん（きゅうこいずみけじゅうたくしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都大田区南久が原2-26-19","lat":35.575245,"lng":139.685822,"geo_status":"db","era":"昭和26","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造2階建、瓦葺、建築面積39㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"13 － 0131","desc":"木造２階建，桟瓦葺で，昭和２５年開設の住宅金融公庫融資を受けて施主自らが設計した。融資上限の建坪１８坪で達成した明快な平面や形態など，工夫が凝らされている。当時の公的融資による住宅建築の有り様を示す戦後復興期の庶民住宅の好例といえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002759"},{"id":"00009922","register_sub_id":"101","register_pk":"196069","name":"白百合女子大学めぐみ荘（旧菊池家住宅主屋）","kana":"しらゆりじょしだいがくめぐみそう（きゅうきくちけじゅうたくしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都調布市緑ヶ丘1-25-1","lat":35.6694546,"lng":139.58049981,"geo_status":"db","era":"明治前期／昭和5・昭和42移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積228㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0337","desc":"伊豆修善寺から移築された名主宅の主屋。木造平屋建で桟瓦葺屋根に越屋根をあげる。左手を土間とし、広間との境に太い大黒柱を立てる。床上部は六間取系で、前面の座敷二室に縁を廻らし、中ノ間に式台の痕跡を有す。原所在地でも希少となっている大型民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009922"},{"id":"00000638","register_sub_id":"101","register_pk":"101628","name":"新町館（三宅家住宅）","kana":"しんまちかん（みやけけじゅうたく）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区白山1-29-5","lat":35.71930817,"lng":139.75306107,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造地下１階地上３階建，建築面積57㎡","structure_material":"鉄筋コンクリート造地下１階地上３階建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0019","desc":"住宅兼法律事務所として建てられ，工事中に関東大震災に遭う。鉄筋コンクリート造陸屋根住宅の初期のもの。箱形の容器に縦長の開口部を穿ち，北面に玄関ポーチ，南面にベイウィンドウを設ける。ドイツ壁の仕上げとし，軒下にトリグリフ状の飾りを付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000638"},{"id":"00008658","register_sub_id":"101","register_pk":"149379","name":"鈴木家住宅主屋","kana":"すずきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都新宿区横寺町31-11","lat":35.70306835,"lng":139.73516215,"geo_status":"db","era":"昭和22年／昭和28年改修","year":1947,"year_source":"converted","year_min":1947,"year_max":1947,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積116㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"13 － 0281","desc":"神楽坂地区の小路に北面する。木造平屋建、建築面積116㎡。切妻造妻入桟瓦葺で、正面に深い下屋を設ける。中廊下式で東から南にかけて居間や食堂、居室を配する。格子戸をたてるなど和風を基調としながら、煉瓦貼玄関や名栗仕上げの軸部などを散りばめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008658"},{"id":"00003197","register_sub_id":"101","register_pk":"104187","name":"瀬川家住宅（旧古市家住宅）蔵","kana":"せがわけじゅうたく（きゅうふるいちけじゅうたく）くら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区本郷2-134-1","lat":35.70654733,"lng":139.75799551,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造2階建、瓦葺、建築面積11㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"13 － 0141","desc":"茶道具等保管のため茶室等とともに増築。鉄筋コンクリート造，２階建，桟瓦葺で，外部は中塗仕上とし軒に太めの鉢巻を回す。台所と蔵前が一体に接続され，内部は天井を漆喰塗，内壁は全面板張とする。立ちの低い主屋増築部とともに屋敷最奥の構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003197"},{"id":"00003196","register_sub_id":"101","register_pk":"104186","name":"瀬川家住宅（旧古市家住宅）主屋","kana":"せがわけじゅうたく（きゅうふるいちけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都文京区本郷2-134-1","lat":35.706432,"lng":139.757843,"geo_status":"db","era":"明治20頃／昭和初期増築","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積270㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"13 － 0140","desc":"日本近代土木の祖古市公威邸として建設。玄関に続き能舞台ともなる応接間，主座敷があり，奥に広間と三畳台目の茶室がある。栂や杉丸太を用いた端正な和風を基調に，応接間のトップライト，板床寄木張など近代の要素が導入され，新感覚の造形を実現している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003196"},{"id":"00006807","register_sub_id":"101","register_pk":"107789","name":"タイガービルヂング","kana":"たいがーびるぢんぐ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都台東区蔵前4-13","lat":35.705219,"lng":139.790283,"geo_status":"db","era":"昭和初期／昭和30改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造5階地下1階建、建築面積301㎡、塔屋2ヶ所付","structure_material":"鉄筋コンクリート造5階地下1階建","registered":"2008.03.07(平成20.03.07)","register_no":"13 － 0226","desc":"国際通りに東面して建つ。建築面積３０１㎡、鉄筋コンクリート造、地上５階、地下１階、外壁はスクラッチタイル貼とする。正面外壁両端に円窓を配し、外壁頂部はレリーフで飾る。当初はエレベーター付の高級賃貸集合住宅として建てられた。震災復興建築の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006807"},{"id":"00002368","register_sub_id":"101","register_pk":"103358","name":"台東区立朝倉彫塑館東屋","kana":"たいとうくりつあさくらちょうそかんあずまや","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都台東区谷中7-18-10","lat":35.72693524,"lng":139.76837028,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積4.0㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"13 － 0110","desc":"諏訪台通りに面して開けられた正門を入って左手，敷地の北西隅に在って，アトリエ棟表玄関に向き合うように建つ。南東面を入口とした五角形平面，数寄屋意匠の待合的東屋で，北と西の２面に腰掛を設け，傘状垂木の緩勾配，銅板葺の宝形屋根を架ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002368"},{"id":"00002365","register_sub_id":"101","register_pk":"103355","name":"台東区立朝倉彫塑館アトリエ棟","kana":"たいとうくりつあさくらちょうそかんあとりえとう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都台東区谷中7-18-10","lat":35.72685139,"lng":139.76850116,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造3階建、一部地下階付、建築面積280㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2001.10.12(平成13.10.12)","register_no":"13 － 0107","desc":"彫刻家朝倉文夫のアトリエとして知られる。鉄筋コンクリート造３階建で，朝倉文夫自身の設計になり，曲面を多用したアトリエ，数寄屋意匠の玄関ホール・３階朝陽の間など独特の個性的デザインが随所に見られる。現在は彫刻美術館として公開されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002365"},{"id":"00002367","register_sub_id":"101","register_pk":"103357","name":"台東区立朝倉彫塑館旧アトリエ","kana":"たいとうくりつあさくらちょうそかんきゅうあとりえ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都台東区谷中7-18-10","lat":35.72692878,"lng":139.76887889,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"13 － 0109","desc":"住居棟の東，天王寺寄りに建つ。関東大震災後の復興アトリエで，現在の彫塑館が完成する過程の起点となったもの。北東，南東，西南の３隅を隅切とし，北面に天窓を設けた宝形屋根を架け，頂上に「浴光」と題された裸婦像を載せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002367"},{"id":"00002366","register_sub_id":"101","register_pk":"103356","name":"台東区立朝倉彫塑館住居","kana":"たいとうくりつあさくらちょうそかんじゅうきょ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都台東区谷中7-18-10","lat":35.72696528,"lng":139.76876989,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建及び鉄筋コンクリート平屋建、瓦葺、建築面積260㎡","structure_material":"木造2階建及び鉄筋コンクリート平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"13 － 0108","desc":"アトリエ棟の東に造庭した「五典の水庭」を囲うように建つ木造和風建築で，東側に裏玄関，北側に２階建の居住部，北東に台所と浴室，南側に渡廊下を配し，南西端の応接室でアトリエ棟書斎に連絡する。裏玄関・居住部・応接室等は朝倉文夫好みの数寄屋の造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002366"},{"id":"00014568","register_sub_id":"101","register_pk":"515110","name":"髙木家住宅離れ","kana":"たかぎけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区本駒込三丁目240-7","lat":35.73065,"lng":139.75358333,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"13 - 0483","desc":"都指定史跡駒込名主屋敷の敷地内にあり主屋西奥に渡り廊下を介して建つ。木造平屋建寄棟造桟瓦葺で、八畳と六畳の続き間座敷の南東に縁を廻す。床の間廻りに銘木を用い、床脇と平書院を備える近代和風。史跡の主屋等と建ち並び歴史的な屋敷構えの一翼を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014568"},{"id":"00014569","register_sub_id":"101","register_pk":"515111","name":"髙木家住宅洋館","kana":"たかぎけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区本駒込三丁目240-7","lat":35.73057778,"lng":139.75389167,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"13 - 0484","desc":"主屋の南東にやや離れて建つ陸屋根の木造平屋建で接客兼ビリヤード室。下見板張の外壁に縦長の両開き窓が並ぶ洋風の外観。内部は前室と洋間の二室で、天井と壁ともに漆喰塗、腰は竪羽目板張。内外共に洋風の旧状をよく残し、屋敷構えのアクセントとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014569"},{"id":"00012131","register_sub_id":"101","register_pk":"352930","name":"髙橋家住宅衣装蔵","kana":"たかはしけじゅうたくいしょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都西東京市下保谷三丁目862","lat":35.753048,"lng":139.564976,"geo_status":"db","era":"明治8年頃／昭和47年増築、昭和62年改修","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、金属板葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"13-398","desc":"主屋の北に南面して建つ。桁行三間、梁間三間、土蔵造二階建で、切妻造の置屋根形式。外壁は漆喰塗で昭和の改修で腰部を人造石洗出し仕上げとする。東南面の扉口と窓の観音扉は黒漆喰を施し、水切と鉢巻を廻らす丁寧な造りで、敷地の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012131"},{"id":"00012133","register_sub_id":"101","register_pk":"352932","name":"髙橋家住宅表門","kana":"たかはしけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都西東京市下保谷三丁目862","lat":35.752596,"lng":139.565262,"geo_status":"db","era":"明治期／昭和30年頃改修","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造、銅板葺、間口2.7m、左右袖塀付","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"13-400","desc":"主屋の南方に建つ。一間薬医門で、切妻造銅板葺の屋根を架け、左右両脇に袖塀を付ける。間口二・七メートルと広く、両開板扉をたてこむ。比較的規模が大きく、表構えの軸部は木太く堂々たる外観をみせ、屋敷地に風格を添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012133"},{"id":"00012129","register_sub_id":"101","register_pk":"352928","name":"髙橋家住宅主屋","kana":"たかはしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都西東京市下保谷三丁目862-5他","lat":35.752909,"lng":139.565049,"geo_status":"db","era":"昭和2年／昭和55年改修、平成23年増築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積192㎡","structure_material":"木造平屋一部2階建","registered":"2018.03.27(平成30.03.27)","register_no":"13-396","desc":"敷地奥に東西棟で建つ。入母屋造の表玄関、切妻造の裏玄関を並べ、中廊下を通して生活空間と接客空間を配する。内部は和風でまとめ、一、二階とも座敷飾りに洗練された意匠をみせるが、洋小屋やガラス建具の使用などに都市近郊農家の近代化を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012129"},{"id":"00012130","register_sub_id":"101","register_pk":"352929","name":"髙橋家住宅土蔵","kana":"たかはしけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都西東京市下保谷三丁目862","lat":35.752826,"lng":139.565276,"geo_status":"db","era":"明治8年／大正12年・平成19年改修","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、金属板葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"13-397","desc":"主屋の南東に西面して建つ。桁行四間、梁間二間、土蔵造二階建、切妻造の置屋根形式で、小屋は和小屋である。外壁は漆喰塗で、関東大震災後に鉄板を張る。扉口や二階南面の窓に観音扉を開き、窓庇の持送りには繰形の彫刻を施し、敷地の歴史的景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012130"},{"id":"00012132","register_sub_id":"101","register_pk":"352931","name":"髙橋家住宅納屋","kana":"たかはしけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都西東京市下保谷三丁目862","lat":35.75299,"lng":139.565225,"geo_status":"db","era":"江戸末期／昭和前期増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、金属板葺、建築面積52㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"13-399","desc":"主屋の北東に建つ。桁行四間半、梁間三間、木造二階建で、西面に吹放ちの下屋を設ける。もと平屋建の馬屋で、戦前までに二階が増築されたが、柱、梁など軸組は旧態をよく留めている。農家の屋敷構えや構成を知るうえで欠かせない要素の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012132"},{"id":"00014233","register_sub_id":"101","register_pk":"509623","name":"高畠家住宅主屋","kana":"たかばたけけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都千代田区神田駿河台四丁目2-9","lat":35.69781389,"lng":139.76654722,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積149㎡","structure_material":"木造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"13 - 0462","desc":"駿河台に所在する近代和風住宅で実業家の隠居所として建設。入母屋造桟瓦葺、霧除庇銅板葺、外壁は真壁造一部下見板張で、間取りは中廊下型。コンクリート基礎、床組の火打梁、補強金具等、耐震に配慮した関東大震災復興建築で、往時の町の景観を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014233"},{"id":"00014234","register_sub_id":"101","register_pk":"509624","name":"高畠家住宅正門","kana":"たかばたけけじゅうたくせいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都千代田区神田駿河台四丁目2-9","lat":35.69780278,"lng":139.76662778,"geo_status":"db","era":"大正15年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造、瓦葺、間口1.9m","structure_material":"木造","registered":"2022.06.29(令和4.06.29)","register_no":"13 - 0463","desc":"駿河台にある近代和風住宅の屋敷正面石垣に開く腕木門。切妻造桟瓦葺の起り屋根とした数寄屋風の門で、引分け大戸の鏡板は一枚板で、南袖に潜り戸を設ける。屋根上に塀を通し、軒先や長押を石垣の高さに揃えるなど、調和がとれた外観で歴史的景観を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014234"},{"id":"00014235","register_sub_id":"101","register_pk":"509625","name":"高畠家住宅塀及び石垣","kana":"たかばたけけじゅうたくへいおよびいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都千代田区神田駿河台四丁目2-9","lat":35.69788889,"lng":139.76658611,"geo_status":"db","era":"大正15年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造、瓦葺、総延長39m","structure_material":"木造","registered":"2022.06.29(令和4.06.29)","register_no":"13 - 0464","desc":"駿河台にある近代和風住宅の敷地北側面から東正面に巡る塀と石垣。石垣は間知石布積で空積とし、正面南側に車庫を設ける。塀は桟瓦葺、真壁造漆喰仕上腰板張で、石垣の笠石に載り、鉄骨で控柱を付す。屋敷の堂々たる構えを構成し、歴史的景観を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014235"},{"id":"00008099","register_sub_id":"101","register_pk":"132497","name":"田口家住宅主屋","kana":"たぐちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都文京区西片2-10-14","lat":35.7159435,"lng":139.756609,"geo_status":"db","era":"明治18年／明治22年・明治後期増築・昭和50年・平成20年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積200㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"13 － 0258","desc":"敷地中央に台所や和室等の居室棟、北隅に離れ、東隅に書斎等の洋館を配し、玄関が４５度振れて居室棟と洋館との間に南面して建つ。木造平屋建で、寄棟や切妻を組み合わせる桟瓦葺屋根とする。下見板張の洋館と起り屋根の玄関の対比が特徴的な外観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008099"},{"id":"00001763","register_sub_id":"101","register_pk":"102753","name":"竹中家住宅主屋","kana":"たけなかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都大田区田園調布3-12-10","lat":35.59919228,"lng":139.66381569,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積225㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"13 － 0090","desc":"田園調布住宅街の一角に建つ木造２階建の建物。外観は応接室部を竪板張，その他を簓子下見板張とし，街路に向かって大小複数の妻面を見せる。中廊下を持つ書院造風の部分と玄関脇のテラス付応接室からなり，昭和初期の中流家庭住宅の一つの典型を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001763"},{"id":"00003845","register_sub_id":"101","register_pk":"104835","name":"椿山荘残月","kana":"ちんざんそうざんげつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都文京区関口2-10-8","lat":35.71134754,"lng":139.7250656,"geo_status":"db","era":"大正中期／昭和22移築","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦葺一部銅板葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"13 － 0164","desc":"大正７年に完成した箱根小湧園の藤田別邸から移築された。木造平屋建，桟瓦葺で，中心となる座敷には京都表千家の残月亭写しの残月床を構える。栂などの良材を用いており，室内から軒廻りに至るまで，全体を繊細な比例で纏め上げた質の高い数寄屋造である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003845"},{"id":"00011886","register_sub_id":"101","register_pk":"211151","name":"塚﨑家住宅主屋","kana":"つかざきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都大田区山王二丁目2370-3","lat":35.587655,"lng":139.725336,"geo_status":"db","era":"大正13年／昭和33年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階一部地下一階建、瓦葺、建築面積116㎡、地下室付","structure_material":"木造2階一部地下一階建","registered":"2017.10.27(平成29.10.27)","register_no":"13-383","desc":"大森山王の地に建つ木造二階建地下室付の住宅。大谷石を多用し、深い水平軒を伸ばす。外観は一階をスクラッチタイル、二階をハーフティンバーでまとめ、屋根は寄棟造桟瓦葺。内部は洋室を中心とするが、一、二階に座敷を有する。大正期の洋風住宅建築の秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011886"},{"id":"00011887","register_sub_id":"101","register_pk":"211152","name":"塚﨑家住宅門及び塀","kana":"つかざきけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都大田区山王二丁目2370-3","lat":35.587743,"lng":139.725383,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"正門 木造、間口2.2m 通用門 木造、間口1.3m、塀 石造、総延長25m、ポンプ室付","structure_material":"正門 木造","registered":"2017.10.27(平成29.10.27)","register_no":"13-384","desc":"敷地北面街路側と西面北寄りを画す。北面西寄りに門口を開き、北西隅には木造二階建のポンプ室を配する。門柱は重厚な石造で、左右に延びる塀はスクラッチタイル貼で上部の色を変えて軽快に見せる。西面は大谷石を高く積む。主屋と共通の意匠を持つ門及び塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011887"},{"id":"00006420","register_sub_id":"101","register_pk":"107403","name":"築山家住宅石垣","kana":"つきやまけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都世田谷区砧8-18-12","lat":35.64052389,"lng":139.60594735,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"石造、折曲り延長59m","structure_material":"石造","registered":"2007.10.02(平成19.10.02)","register_no":"13 － 0219","desc":"道路から０．７ｍほど高く造成された宅地の土留を兼ねる。敷地の北辺と東辺、及び玄関前アプローチ部の外周に築く。０．２４ｍ×０．９ｍの大谷石を３段に積み、笠石をのせ、要所に控えをとる。生垣とともに、落ち着いた住宅地景観の形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006420"},{"id":"00006746","register_sub_id":"101","register_pk":"107729","name":"築山家住宅主屋","kana":"つきやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都世田谷区砧8-18-12","lat":35.640442,"lng":139.605957,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積158㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"13 － 0217","desc":"小田急小田原線の南側、区画整理事業による住宅地に建つ。住宅作家山田醇の設計による住宅作品で、中廊下型の平面、南面の幅広の縁側とテラス、急傾斜の切妻屋根と大きな突き上げ状屋根窓、ハーフティンバー風の妻面処理等に山田醇の作風がよく示されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006746"},{"id":"00006421","register_sub_id":"101","register_pk":"107404","name":"築山家住宅水蓮池","kana":"つきやまけじゅうたくすいれんいけ","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都世田谷区砧8-18-12","lat":35.64041734,"lng":139.60606718,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"石造、面積6.4㎡","structure_material":"石造","registered":"2007.10.02(平成19.10.02)","register_no":"13 － 0220","desc":"敷地の南東部、主屋南面東端の老人室の南方に位置する。大谷石で築かれた南北に長い幅１．２ｍ、長４．１ｍ規模の池で、周囲に幅０．１３ｍの縁石を廻し、４隅に０．２４ｍ×０．２９ｍの角石を配して十字形状とする。山田醇設計住宅によく見られる庭園設備。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006421"},{"id":"00006419","register_sub_id":"101","register_pk":"107402","name":"築山家住宅門","kana":"つきやまけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都世田谷区砧8-18-12","lat":35.64042683,"lng":139.60583075,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"石造、間口1.8m、石段・石畳及び石造花壇付","structure_material":"石造","registered":"2007.10.02(平成19.10.02)","register_no":"13 － 0218","desc":"主屋西面の玄関に対応し、北側道路に面して間口１．８ｍの門を開く。門柱は０．６ｍ角、高さ１．５ｍとし、大谷石を７段に積み笠石を置く。玄関前まで矩折れにコンクリート平板を敷き、外周の石垣と花壇、玄関前の石段とともに良好なアプローチ空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006419"},{"id":"00013359","register_sub_id":"101","register_pk":"368446","name":"津雲家住宅主屋","kana":"つくもけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都青梅市住江町72-2他","lat":35.78828611,"lng":139.26158056,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積229㎡","structure_material":"木造平屋一部2階建","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0437","desc":"地元選出の国会議員が自邸に設けた迎賓棟。玄関の西は八畳茶室、東は一階板間に床棚を構える座敷、二階が大広間で南縁から多摩川を見晴らす。玄関北東の八畳座敷は酒蔵古材の梁を見せ、西に台所が続く。京都と地元の大工の協働で上質な接客空間を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013359"},{"id":"00013361","register_sub_id":"101","register_pk":"368448","name":"津雲家住宅塀","kana":"つくもけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都青梅市住江町72-2他","lat":35.78825556,"lng":139.26143611,"geo_status":"db","era":"昭和9年頃","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造、瓦葺、総延長28m","structure_material":"鉄筋コンクリート造","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0439","desc":"敷地西辺を画する鉄筋コンクリート造の塀である。門南北の高い石垣上に建ち、コンクリート布基礎を据えて柱形を見せる。内側には控柱を付す。柱間は下見板形に目地を入れる。刳形付の腕木で軒を支え、屋根を桟瓦葺とする。表構えに端正な表情を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013361"},{"id":"00013360","register_sub_id":"101","register_pk":"368447","name":"津雲家住宅門","kana":"つくもけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都青梅市住江町72-2","lat":35.7883,"lng":139.261475,"geo_status":"db","era":"昭和9年頃","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造、瓦葺、間口2.0m、左右袖壁付","structure_material":"木造","registered":"2020.08.17(令和2.08.17)","register_no":"13 － 0438","desc":"敷地の西辺中央に設けた表門で、自然石基壇に建つ棟門である。屋根は切妻造桟瓦葺で、軒先と螻羽を銅板で葺く。門柱は節を出した磨丸太で、冠木の鼻に柱を立て、脇壁を中塗仕上とする。梁以上の小屋組も磨丸太で、趣味性の強い迎賓施設の導入を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013360"},{"id":"00007978","register_sub_id":"101","register_pk":"128810","name":"辻家住宅旧主屋","kana":"つじけじゅうたくきゅうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都杉並区松庵2-102","lat":35.69851182,"lng":139.59668257,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積175㎡","structure_material":"木造2階一部平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"13-0256","desc":"南北に通る道路に東面する敷地に建つ。木造２階建、東西棟の入母屋造妻入桟瓦葺。東南隅に陸屋根平屋建で洋間の応接室、その北隣に入母屋の妻を見せる玄関を出し、西面に老人室や納戸などを付設。郊外に建つ洋間付和風住宅で、建具や欄間に繊細な意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007978"},{"id":"00007192","register_sub_id":"101","register_pk":"108174","name":"照田家住宅主屋","kana":"てるたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都墨田区緑2-8-4","lat":35.69377745,"lng":139.80056628,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積150㎡","structure_material":"木造平屋一部2階建","registered":"2008.07.08(平成20.07.08)","register_no":"13 － 0233","desc":"敷地の中央に建ち、南に庭園を造る。入母屋造２階建の座敷棟を中心に、平屋建の茶室棟や玄関・応接間棟、風呂・厨房棟などを付設。座敷や茶室などは銘木を多用し、繊細な意匠でまとめる。応接間は床を寄木張、柱を名栗仕上げとし、タイル貼のベランダを付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007192"},{"id":"00000652","register_sub_id":"101","register_pk":"101642","name":"東京女子大学17号館（ライシャワー館）","kana":"とうきょうじょしだいがくじゅうななごうかん（らいしゃわーかん）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都杉並区善福寺2-6-1","lat":35.71123481,"lng":139.59174442,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造一部木造２階建，瓦葺，建築面積184㎡","structure_material":"鉄筋コンクリート造一部木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0033","desc":"創立者のひとりであるライシャワーの住宅として建設されたもの。本館の裏側，構内の北東隅に位置し，外国人教師館・安井記念館と鼎立する。レーモンドがライトの影響下から脱しつつあった時期の鉄筋コンクリート造住宅になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000652"},{"id":"00000650","register_sub_id":"101","register_pk":"101640","name":"東京女子大学14号館（安井記念館）","kana":"とうきょうじょしだいがくじゅうよんごうかん（やすいきねんかん）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都杉並区善福寺2-6-1","lat":35.71116467,"lng":139.59081252,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造２階建，瓦葺，建築面積111㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0031","desc":"初代学監安井てつの住宅として建設。大正１０年着工の第一期工事分の建物であるが，着工は関東大震災後の大正１３年８月になり，震災前の着工になるライト調の外国人教師館よりは，ほぼ１年遅れのライシャワー館に近い造形意匠をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000650"},{"id":"00000651","register_sub_id":"101","register_pk":"101641","name":"東京女子大学16号館（外国人教師館）","kana":"とうきょうじょしだいがくじゅうろくごうかん（がいこくじんきょうしかん）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都杉並区善福寺2-6-1","lat":35.71140516,"lng":139.5912935,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造２階建，瓦葺，建築面積228㎡","structure_material":"鉄筋コンクリート造一部鉄骨造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0032","desc":"階上４戸、階下共用の集合住宅的施設。大正１０年着工の第一期工事に属する建物で，水平線を強調した軒や庇，庇上の花台台座の飾り，ポーチ支持柱の柱頭飾りなどにライト調を色濃く感じさせる。ライトの影響下にあったレーモンドの初期作品でもある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000651"},{"id":"00014759","register_sub_id":"101","register_pk":"519017","name":"冨澤家住宅主屋","kana":"とみざわけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都足立区柳原一丁目21-2","lat":35.74525,"lng":139.81479167,"geo_status":"db","era":"大正前期／昭和前期増築、平成21年改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋一部2階建、瓦葺、建築面積157㎡","structure_material":"木造平屋一部2階建","registered":"2024.03.06(令和6.03.06)","register_no":"13 - 0504","desc":"荒川右岸の柳原に位置する和風住宅の主屋。平屋一部二階建桟瓦葺南北棟で、北西に増築棟を突出し全体は矩折れの平面とする。内部は北東隅を土間、南を2列4室、南半は2室続きの座敷で庭に面し縁を廻らす。正面に格子構えなど残し、地域の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014759"},{"id":"00002757","register_sub_id":"101","register_pk":"103747","name":"鳥海家住宅主屋","kana":"とりうみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都大田区東矢口1-3-11","lat":35.567135,"lng":139.705719,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積202㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"13 － 0129","desc":"昭和初期に宅地開発された蒲田駅近郊にある。南面して建つ東西に長い平家建（一部２階建）で，南東部には洋風の玄関・応接間・書斎を配するが，他は中廊下式で明快な平面計画をもつ和風住宅である。昭和前期の都市住宅の形式と意匠を示した好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002757"},{"id":"00005260","register_sub_id":"101","register_pk":"106248","name":"中島家住宅主屋","kana":"なかじまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都三鷹市上連雀5-7-3","lat":35.694817,"lng":139.553528,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積159㎡","structure_material":"木造平屋一部2階建","registered":"2006.03.02(平成18.03.02)","register_no":"13 － 0196","desc":"東面敷地のやや北寄りに建ち，桁行８間，梁間５間規模の木造平屋一部２階建で，寄棟造，桟瓦葺とする。主な居室を和室とするが応接室及び書斎を洋室とし，ステンドグラス窓や丸窓を用いるなど，昭和初期の和洋折衷の郊外住宅の特徴を良く残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005260"},{"id":"00001659","register_sub_id":"101","register_pk":"102649","name":"中野家住宅蔵","kana":"なかのけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都立川市柏町3-8-2","lat":35.72349434,"lng":139.41690641,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"土蔵造、瓦葺、建築面積76㎡","structure_material":"土蔵造","registered":"2000.04.28(平成12.04.28)","register_no":"13 － 0084","desc":"主屋の西北に建つ桁行４間、梁行２間半の２階建、南北棟、切妻造の土蔵で、主屋の西面に接続して南前面に１０畳床の間付きの蔵前をはりだす。階下は１０畳と７畳半の２室から成り、奥の座敷北側に床の間を付けて蔵座敷とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001659"},{"id":"00001658","register_sub_id":"101","register_pk":"102648","name":"中野家住宅主屋","kana":"なかのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都立川市柏町3-8-1","lat":35.72340955,"lng":139.41703469,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積220㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"13 － 0083","desc":"武蔵野の面影を残す短冊状の区画の南方、五日市街道に面した約７００坪の敷地の中央に南面して建つ。木造２階建、入母屋造で、桁行１０間梁行６間の規模を有し、六間取り型式をとる。正面東端の入母屋破風の玄関構えに絹屋としての繁栄振りがうかがわれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001658"},{"id":"00013232","register_sub_id":"101","register_pk":"366221","name":"長濱家住宅主屋","kana":"ながはまけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都品川区平塚一丁目584","lat":35.616225,"lng":139.71604444,"geo_status":"db","era":"大正10年頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、瓦葺、建築面積77㎡、床下倉庫付","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"13 － 0428","desc":"国道西側の住宅地に建つ入母屋造桟瓦葺の主屋。建ちの高い二階建で、南面東端に起り付入母屋造屋根の玄関を構える。玄関は格天井で、客間も良材を用いた丁寧なつくりとする。二階の座敷からは南面の広縁を介して庭を望む。戦災を免れた上質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013232"},{"id":"00013233","register_sub_id":"101","register_pk":"366222","name":"長濱家住宅門","kana":"ながはまけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都品川区平塚一丁目584","lat":35.616225,"lng":139.71604444,"geo_status":"db","era":"大正10年頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造、銅板葺、間口1.8m、左右袖塀付","structure_material":"木造","registered":"2020.04.03(令和2.04.03)","register_no":"13 － 0429","desc":"敷地南辺、道路に面して建つ切妻造銅板葺の一間腕木門。軸部に杉丸太を用い、軒裏を網代で仕上げる。両側の袖塀は矩折れに張り出し、門より一段低い切妻屋根を置く。壁は鼠漆喰塗で腰より下を竪板張とし、東に脇戸を開く。道路景観を彩る数寄屋風の瀟洒な門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013233"},{"id":"00008831","register_sub_id":"101","register_pk":"162274","name":"中村家住宅主屋","kana":"なかむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都西多摩郡檜原村2478","lat":35.72668808,"lng":139.04911651,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、茅葺（銅板仮葺）、建築面積184㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"13 － 0290","desc":"山間地の古道に面して建つ。桁行17.3ｍ梁間10.9ｍ、入母屋造茅葺（銅板仮葺）で、両妻の下部を兜屋根風につくる独特な形態をもつ。内部には神殿を設えて、その前面に社務所と称する玄関を構える。社家住宅の特徴を備える大型民家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008831"},{"id":"00009722","register_sub_id":"101","register_pk":"195551","name":"中村家住宅洋館","kana":"なかむらけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都中野区中野1-31-1","lat":35.70426884,"lng":139.67267492,"geo_status":"db","era":"明治後期／大正4移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積76㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0307","desc":"中野駅南東の五叉路に面した敷地に建つ。木造二階建桟瓦葺で南面に玄関を突出させる。外壁は下見板張で、窓枠上部のペディメントや窓庇屋根軒先の飾板などに洋風意匠を示す。二階には暖炉付の洋間と、トコを備えた和室を並べる。当時の素封家の生活様式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009722"},{"id":"00012306","register_sub_id":"101","register_pk":"531630","name":"並木ハウス","kana":"なみきはうす","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都豊島区雑司が谷三丁目32-1","lat":35.72113333,"lng":139.714825,"geo_status":"db","era":"昭和28年／平成21年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積106㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"13-412","desc":"雑司ヶ谷鬼子母神堂の参道の路地奥に西面して建つ。木造二階建で、切妻屋根をＴ字にかける。北に階段や共用部をまとめ、幅広の中廊下を通し、三方に大小の部屋を配する。床の間付の部屋もある上質な仕様の木造賃貸アパートで、手摺の意匠にも気品がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012306"},{"id":"00011275","register_sub_id":"101","register_pk":"209111","name":"西川家旧別邸蔵","kana":"にしかわけきゅうべっていくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都昭島市中神町二丁目15-3他","lat":35.700808,"lng":139.374743,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"鉄筋コンクリート造2階建、瓦葺、建築面積32㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"13－0373","desc":"西川製糸創業者が別邸として営んだ宅地に現存する。鉄筋コンクリート造二階建。小屋は木造でキングポストトラス。折釘や鉢巻など伝統的な土蔵の外観を踏襲しながら、外壁には石造風の目地を入れた意匠を持つ。初期の本格的な鉄筋コンクリート造建築の希少例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011275"},{"id":"00001504","register_sub_id":"101","register_pk":"102494","name":"萩原家住宅","kana":"はぎわらけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都世田谷区三宿1-15-2","lat":35.64760434,"lng":139.67538017,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積98㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"13 － 0075","desc":"木造大壁造で，当初は平屋建であったが昭和１０年頃に旧露台部分に２階を増築。水平を強調した外観や，東西１列に居室を並べ背後に書斎が張り出したＴ字型平面に特色がある。三軒茶屋一帯が住宅地として開けた初期の住宅として，また遠藤新の作品として重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001504"},{"id":"00000759","register_sub_id":"101","register_pk":"101749","name":"橋本家住宅","kana":"はしもとけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都文京区西片2-8-11","lat":35.71591085,"lng":139.75469251,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造２階建，瓦葺，建築面積65㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0035","desc":"木造２階建の洋館で,玄関回りを除く階下をモルタル塗,階上をドイツ壁とする。見切りをとらずに仕様を変える外壁仕上げは珍しい。玄関上部バルコニー手摺りの親柱意匠も特徴的。寄棟を切り落とした袴腰型の妻面に木部を現してハーフティンバー風とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000759"},{"id":"00001904","register_sub_id":"101","register_pk":"102894","name":"長谷川家住宅","kana":"はせがわけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都世田谷区代田6-5-11","lat":35.66289276,"lng":139.66396314,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積84㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"13 － 0095","desc":"小田急線開通後，箱根土地が丘陵地に開発した守山分譲地に建つ。切妻造・桟瓦葺の大屋根窓付き急傾斜屋根を冠す，木造２階建，外壁モルタル塗の山荘風建築。内部で暖炉付き居間兼応接室と出窓付き食堂が連続する。大正末期・昭和初期の洋風住宅建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001904"},{"id":"00008265","register_sub_id":"101","register_pk":"133907","name":"濵家住宅西洋館","kana":"はまけじゅうたくせいようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都武蔵野市吉祥寺北町三丁目952-614","lat":35.71375759,"lng":139.57144663,"geo_status":"db","era":"大正後期／昭和40年・昭和50年・昭和52年・昭和60年・平成10年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、スレート葺一部鋼板葺、建築面積116㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"13 － 0264","desc":"北面が道路に接する矩形敷地の北寄りに位置し、ポーチを東に張り出す。木造２階建、寄棟造スレート葺、建築面積１４１㎡。アメリカから輸入したプレファブ住宅で、外壁は下見板張、木製の上下窓もよく残る。洋風住宅として閑静な住宅街に彩りを添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008265"},{"id":"00002619","register_sub_id":"101","register_pk":"103609","name":"ビストロＯＪＩ（末光家住宅）","kana":"びすとろおじ（すえみつけじゅうたく）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都杉並区上荻2-178","lat":35.7071633,"lng":139.61120312,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、スレート葺、建築面積117㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"13 － 0124","desc":"関東大震災後の区画整理事業で整備された街路の角地にある。外装下見板張で，北面をマンサード風屋根とし，南面は屋根の傾斜を変えて採光を意識した造りとする。四周に縦長窓を配し，東妻面隅の屋根付出窓とハーフチンバー風の破風が街路景観に彩りを添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002619"},{"id":"00014574","register_sub_id":"101","register_pk":"515116","name":"平田家住宅主屋","kana":"ひらたけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都世田谷区代田六丁目955-5他","lat":35.66291111,"lng":139.66435833,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積168㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"13 - 0489","desc":"下北沢駅西北の住宅地に建つ住宅。東を玄関とした中廊下式の平面で、北に水廻りや内玄関、南にサンルーム付応接室や座敷を配し、南庭沿いに縁を巡らす。二階は東に洋室二室、西に座敷二室を配す。室内各所に銘木を多用し、洗練された和洋折衷の住宅建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014574"},{"id":"00009593","register_sub_id":"101","register_pk":"194589","name":"平田家住宅主屋","kana":"ひらたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都足立区西保木間2-1658-1","lat":35.80015071,"lng":139.79831519,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積270㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"13 － 0297","desc":"旧日光街道脇に位置し、木造平屋建、入母屋造桟瓦葺に下屋を廻らす。入母屋玄関から中廊下を東にのばし、南面に連続した三室の座敷を配す。北西隅には洋間を配し、フランス瓦を葺いて外観に変化をつける。各所の建具に意匠を凝らすなど、瀟洒な趣きを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009593"},{"id":"00014575","register_sub_id":"101","register_pk":"515117","name":"平田家住宅門及び塀","kana":"ひらたけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都世田谷区代田六丁目955-5他","lat":35.66282778,"lng":139.66446667,"geo_status":"db","era":"昭和12年／昭和35年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"門 鉄筋コンクリート造、瓦葺、間口2.4m 塀 鉄筋コンクリート造、瓦葺、総延長22m","structure_material":"門 鉄筋コンクリート造","registered":"2023.08.07(令和5.08.07)","register_no":"13 - 0490","desc":"下北沢の住宅地に位置する住宅の門及び塀。敷地南辺東端の門は、切妻造桟瓦葺で門柱を鉄筋コンクリート造タイル貼とする。門両脇の塀は腰石積に鉄筋コンクリート造桟瓦葺で下部をタイル貼で飾る。閑静な住宅地に華やかな表構えを形成する丁寧な造りの門と塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014575"},{"id":"00000642","register_sub_id":"101","register_pk":"101632","name":"平野家住宅蔵","kana":"ひらのけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区西片2-9-12","lat":35.71487566,"lng":139.75578358,"geo_status":"db","era":"大正11頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"煉瓦造地下１階地上２階建，瓦葺，建築面積21㎡","structure_material":"煉瓦造地下１階地上２階建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0023","desc":"屋敷地の西端に位置する地下室付きの煉瓦蔵。程良い色合いの焼過煉瓦を用い，覆輪目地で仕上げた丁寧な造りが特徴。窓庇をガラスで葺くなど建築家ならではの技法も認められる。震災前の住宅建築の蔵としても貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000642"},{"id":"00000640","register_sub_id":"101","register_pk":"101630","name":"平野家住宅主屋","kana":"ひらのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区西片2-9-12","lat":35.71494799,"lng":139.75588621,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造２階建，瓦葺，建築面積156㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0021","desc":"わが国最初期の住宅作家とされる保岡勝也による和洋折衷住宅。門を入って右手に洋館，左手に簓子下見の客間棟を配し，正面の玄関の奥に階段室，その裏の縁側と中廊下を繋ぐ廊下を介して茶の間を置く。客間棟の造作，照明器具もよく残っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000640"},{"id":"00000643","register_sub_id":"101","register_pk":"101633","name":"平野家住宅茶室","kana":"ひらのけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区西片2-9-12","lat":35.71488715,"lng":139.75596024,"geo_status":"db","era":"大正11頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積13㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0024","desc":"敷地の中程，客間棟と向き合う位置に建つ。四畳半板床付きの茶室で，東に月見障子を建て込んで開放的な茶室としている。『茶室と茶庭』の著作をもち，茶室にも造詣の深かった保岡勝也設計の近代茶室建築として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000643"},{"id":"00000645","register_sub_id":"101","register_pk":"101635","name":"平野家住宅茶室門","kana":"ひらのけじゅうたくちゃしつもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区西片2-9-12","lat":35.71490227,"lng":139.75610886,"geo_status":"db","era":"大正11頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造棟門，板葺","structure_material":"木造棟門","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0026","desc":"現在は車庫から庭に抜ける位置に移されているが，元来は塀の南端部にあり，茶室への露地の入口門であった。控えをとった門柱にムクリ付き板葺の屋根を載せ，丸竹で棟を押さえている。また，樋の位置にも小丸竹を用いるなどの趣向を凝らしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000645"},{"id":"00000644","register_sub_id":"101","register_pk":"132566","name":"平野家住宅門","kana":"ひらのけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区西片2-9-12","lat":35.71503069,"lng":139.75605778,"geo_status":"db","era":"大正11頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"煉瓦造，瓦葺，左右煉瓦塀付属","structure_material":"煉瓦造","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0025","desc":"門は客間棟と洋館との間に設置され，北袖壁は洋館の外壁に突きつけとする。煉瓦造モルタル塗の門柱に反り付き瓦葺屋根を頂き，両開き木扉の片方に潜り戸を設ける。塀も煉瓦造モルタル塗で，庭側に控えをとる。南端の車庫はもと茶室の入口であったところ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000644"},{"id":"00000641","register_sub_id":"101","register_pk":"101631","name":"平野家住宅洋館","kana":"ひらのけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都文京区西片2-9-12","lat":35.71503062,"lng":139.75598665,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造２階建，スレート葺，建築面積29㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0022","desc":"白タイル貼り（奥向はドイツ壁），ハーフティンバースタイルの洋館。主玄関とは別の玄関と階段室をもち，洋館の独立性を高めている。造作や照明器具もよく残っている。保岡勝也の住宅作風の一端を窺い知るに足る事例とすることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000641"},{"id":"00009914","register_sub_id":"101","register_pk":"196061","name":"淵川家住宅主屋","kana":"ふちかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都杉並区松庵3-101-34","lat":35.7014213,"lng":139.59409103,"geo_status":"db","era":"昭和10頃／昭和13改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋一部2階建、鋼板葺及び瓦葺、建築面積166㎡","structure_material":"木造平屋一部2階建","registered":"2014.04.25(平成26.04.25)","register_no":"13 － 0329","desc":"区内西部の住宅地に建ち、外壁を下見板張とハーフティンバーで構成する切妻造平屋建の洋館と、入母屋造二階建の和館からなる。洋館の玄関はスクラッチタイル貼で、庇に胴張の強い円柱を立て、頂部をスペイン瓦で飾る。戦前の郊外住宅地の面影を残す瀟洒な住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009914"},{"id":"00014576","register_sub_id":"101","register_pk":"515118","name":"ブルーボックスハウス","kana":"ぶるーぼっくすはうす","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"東京都","address":"東京都世田谷区上野毛二丁目95-1他","lat":35.60824167,"lng":139.63723889,"geo_status":"db","era":"昭和46年／昭和後期・令和2年改修","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"鉄筋コンクリート造及び木造平屋地下1階建、鉄板葺、建築面積85㎡、車庫付","structure_material":"鉄筋コンクリート造及び木造平屋地下1階建","registered":"2023.08.07(令和5.08.07)","register_no":"13 - 0491","desc":"世田谷の国分寺崖線に建つ住宅。鉄筋コンクリート造及び木造の混構造で設計は宮脇檀。崖に浮かぶ青色の閉鎖的な箱内部は、上階の庭からガラスで囲った階段室に光を導き、明るい住環境を達成。地形を巧みに用いた独創的な住宅で宮脇檀の革新的作品として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014576"},{"id":"00003852","register_sub_id":"101","register_pk":"104842","name":"前田家住宅外便所","kana":"まえだけじゅうたくそとべんじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都新島村本村2-3-17","lat":34.37862129,"lng":139.25505276,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"石造平屋建、建築面積8.8㎡","structure_material":"石造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"13 － 0171","desc":"桁行３．６ｍ，梁間２．４ｍの長方形平面で，ヴォールト状の屋根を架ける。外壁から屋根まで，すべてを丁寧な石積とし，屋根縁部や気抜きにはコーニスを廻し，開口部にも小庇をつける。新島固有の石材であるコーガ石を用い，洋風細部を備えた石造建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003852"},{"id":"00001661","register_sub_id":"101","register_pk":"102651","name":"真木家住宅日本館","kana":"まきけじゅうたくにほんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都調布市上石原2-48-4","lat":35.65344369,"lng":139.52752772,"geo_status":"db","era":"明治43頃／昭和12移築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積93㎡、渡廊下付","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"13 － 0086","desc":"洋館とともに白金から現在地に移築され、洋館の東方に南面して置かれ、洋館とは渡り廊下でつながれる。木造、平屋建、寄棟造、桟瓦葺で、東南に書院座敷を配する。材料、施工とも上質な造りになり、明治後期の和館洋館併存住宅の事例として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001661"},{"id":"00001660","register_sub_id":"101","register_pk":"102650","name":"真木家住宅洋館","kana":"まきけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都調布市上石原二丁目４８－２１","lat":35.65353245,"lng":139.52738048,"geo_status":"db","era":"明治43頃／昭和12移築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積151㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"13 － 0085","desc":"白金に所在した海軍中将男爵真木長義の邸宅を移築したもの。北面東端にハーフティンバー風の車寄を突出させて玄関とし、南面中央には八角のベイウィンドウを張り出す。外装化粧煉瓦の貼り方や内部ステンドグラスの意匠に新味が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001660"},{"id":"00015154","register_sub_id":"101","register_pk":"530578","name":"松井家住宅表門及び塀","kana":"まついけじゅうたくおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区西片二丁目10-65","lat":35.71401667,"lng":139.75489167,"geo_status":"db","era":"昭和7年頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"表門 木造、瓦葺一部銅板葺、間口3.3m 塀 鉄筋コンクリート造、総延長20m","structure_material":"表門 木造","registered":"2024.12.03(令和6.12.03)","register_no":"13 - 0512","desc":"通りに南面する表門及び塀。表門は切妻造平入桟瓦葺、軒先銅板葺で、上部に桟瓦葺屋根を載せて二重にみせ、柱には出節丸太を用いるなど上質なつくり。塀は鉄筋コンクリート造の万年塀で、外壁モルタル塗洗出仕上とし、門とともに風格ある表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015154"},{"id":"00015152","register_sub_id":"101","register_pk":"530576","name":"松井家住宅主屋","kana":"まついけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区西片二丁目10-6","lat":35.71409722,"lng":139.75494722,"geo_status":"db","era":"昭和7年／平成13年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、銅板葺一部瓦葺、建築面積115㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"13 - 0510","desc":"西片町の中央部に位置する実業家の住宅主屋。敷地西寄りに南面して建つ、２階建入母屋造銅板葺の東西棟で、西に入母屋造の玄関棟を突出。内部は中廊下式平面で、南庭に面して和洋の居室を配す。南東座敷は残月床風の構えなど数寄屋意匠とした上質な和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015152"},{"id":"00015153","register_sub_id":"101","register_pk":"530577","name":"松井家住宅蔵","kana":"まついけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区西片二丁目10-6","lat":35.71417778,"lng":139.75486111,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"土蔵造2階建鉄筋コンクリート造地階付、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建鉄筋コンクリート造地階付","registered":"2024.12.03(令和6.12.03)","register_no":"13 - 0511","desc":"主屋の北西に位置する家財蔵。２階建切妻造妻入桟瓦葺で、外壁モルタル塗仕上に３段の水切を廻らす。地階は鉄筋コンクリート造。各階１室で土間の地階以外は板敷、小屋組は桁行トラスの束に登梁を架ける。窓庇の装飾付側板など凝った外観が敷地景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015153"},{"id":"00010126","register_sub_id":"101","register_pk":"197959","name":"三岸家住宅アトリエ","kana":"みぎしけじゅうたくあとりえ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都中野区上鷺宮2-407","lat":35.727047,"lng":139.636561,"geo_status":"db","era":"昭和9／昭和33改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建及びコンクリートブロック造平屋建、スレート葺、建築面積88㎡","structure_material":"木造2階建及びコンクリートブロック造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"13 － 0347","desc":"画家三岸好太郎・節子夫妻のアトリエ。平明な立面をもつ直方体の主体部南東面に大きく窓を切取り、内部は二層吹抜けのアトリエに螺旋階段を設ける。施主の感性とバウハウスで学んだ設計者の理念が具現化された、都内でも希少な戦前の木造モダニズム建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010126"},{"id":"00002020","register_sub_id":"101","register_pk":"103010","name":"三菱電機高輪荘蔵","kana":"みつびしでんきたかなわそうくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都港区白金台2-6-11","lat":35.63584262,"lng":139.73043245,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造地上3階地下1階建、瓦葺、建築面積41㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2000.12.04(平成12.12.04)","register_no":"13 － 0098","desc":"主屋西北端の厨房部の西側に建つ。地階を車庫とした四層建の鉄筋コンクリート造倉庫で，南面に下屋庇を差し掛けて蔵前を設け，屋根は陸屋根に造る。箱形状の造型意匠に昭和初期の近代土蔵としての特色がよく示されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002020"},{"id":"00002018","register_sub_id":"101","register_pk":"103008","name":"三菱電機高輪荘主屋","kana":"みつびしでんきたかなわそうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都港区白金台2-6-11","lat":35.6357919,"lng":139.73067507,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積410㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"13 － 0096","desc":"株取引で財をなした遠山芳三の東京邸で，明治学院の南方に位置する。木造２階建，入母屋造，桟瓦葺の近代和風邸宅で，東端に玄関と応接室を置き，西方に１０畳・８畳，８畳・８畳，８畳・６畳のセットを雁行させる。山の手の住宅地開発の様相を知る上で貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002018"},{"id":"00002019","register_sub_id":"101","register_pk":"103009","name":"三菱電機高輪荘洋館","kana":"みつびしでんきたかなわそうようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都港区白金台2-6-11","lat":35.63574445,"lng":139.73041514,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積55㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"13 － 0097","desc":"主屋の西方に独立して建つ木造２階建，寄棟造，桟瓦葺の洋館で，北東端の階段上がり口で主屋西端の廊下に接続し，西南端に１間半四方規模のサンルームを張り出す。南庭を臨む主屋の奥座敷とともに和館洋館併存型の住宅構成を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002019"},{"id":"00007343","register_sub_id":"101","register_pk":"108325","name":"水口家住宅洋館","kana":"みなくちけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都杉並区松庵3-35-1","lat":35.7013589,"lng":139.59735345,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積52㎡","structure_material":"木造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"13 － 0236","desc":"敷地北寄りに東西棟で建つ木造２階建洋館。切妻造妻入で、赤色のフランス瓦を葺く。玄関に切妻造のポーチを付け、外壁は正面側西半部をモルタル塗とし、鎧戸付の上げ下げ窓を開け、東半部を下見板張とする。玄関のスカラベをあしらったステンドグラスが印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007343"},{"id":"00012134","register_sub_id":"101","register_pk":"352933","name":"峯岸家住宅主屋","kana":"みねぎしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都西多摩郡檜原村4959","lat":35.75039,"lng":139.081177,"geo_status":"db","era":"江戸末期／明治中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積181㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"13-401","desc":"急峻な斜面の敷地に切妻造の主屋と馬小屋を並べる。主屋は前後二列に五室を配し、土間が狭く板壁や京呂組の梁組など山間部である当地域の特徴を示す。当初は茅葺であったが、明治中期に小屋組を改変し蚕室を設けており、養蚕農家としての変遷をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012134"},{"id":"00003951","register_sub_id":"101","register_pk":"104941","name":"三橋家住宅主屋","kana":"みはしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都大田区久が原6-6-4","lat":35.57639443,"lng":139.69160578,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積88㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"13 － 0172","desc":"東京城南地区に開発された郊外住宅地に建つ。木造２階建，入母屋造，桟瓦葺で，外壁は下見板を高く張り純和風の構えとする。室内は洋間の応接室，食堂以外は和室とするが，居間中心型の整然とした平面を持つ。丁寧なつくりで，昭和初期和風住宅の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003951"},{"id":"00002371","register_sub_id":"101","register_pk":"103361","name":"宮川家住宅主屋","kana":"みやがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都羽村市羽加美4-6-23","lat":35.762524,"lng":139.29808,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積148㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"13 － 0113","desc":"ＪＲ青梅線羽村駅の北西方，多摩川左岸の段丘に位置する阿蘇神社社殿地の南下方に南面して建つ。神社宮司の家柄の住居で，桁行７間半，梁間３間規模，入母屋造，もと茅葺，平入，平面は六間取とし，養蚕に伴う煙出しを載せる。市内現存最古の民家とされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002371"},{"id":"00002372","register_sub_id":"101","register_pk":"103362","name":"宮川家住宅納屋","kana":"みやがわけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都羽村市羽加美4-6-23","lat":35.762501,"lng":139.297974,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積26㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"13 － 0114","desc":"主屋の西南方，多摩川縁の神社参道寄りに建つ。主屋とは棟を直交させた南北棟，入母屋造，もと茅葺の建家で，桁行４間，梁間２間の規模を有する。玉石建，縦板張の簡素な納屋であるが，もとは隠居所と伝え，屋敷構の主要な構成要素であったことを物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002372"},{"id":"00008655","register_sub_id":"101","register_pk":"149376","name":"宮城道雄記念館検校の間","kana":"みやぎみちおきねんかんけんぎょうのま","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都新宿区中町34-1","lat":35.69981057,"lng":139.73650937,"geo_status":"db","era":"昭和23年／昭和25年・昭和30年移築","year":1948,"year_source":"converted","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"13 － 0278","desc":"敷地の西北隅に位置する。木造平屋建、建築面積21㎡の小規模な建物。寄棟造桟瓦葺とし、東・南面には深い庇を出し、外観に陰影を与える。6畳の主室には西面中央にトコ、その両脇に琵琶トコと違棚を構える。洗練された意匠をもつ瀟洒な書斎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008655"},{"id":"00012305","register_sub_id":"101","register_pk":"531629","name":"ミュージアム１９９９（旧千葉常五郎邸）","kana":"みゅーじあむ１９９９（きゅうちばつねごろうてい）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都渋谷区渋谷四丁目107-4","lat":35.65926111,"lng":139.71288056,"geo_status":"db","era":"昭和9年／昭和56年・平成12年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造2階建地下1階、スレート葺、建築面積428㎡","structure_material":"鉄筋コンクリート造2階建地下1階","registered":"2018.05.10(平成30.05.10)","register_no":"13-411","desc":"青山通り裏手にあり東面して建つ。主体部はドーマー窓付の切妻造、中央部に円錐形のエントランスホールと宝形造の玄関ポーチを重ね、華やかな外観をつくる。マントルピースなど細部には幾何学意匠を取入れる。都心に残る昭和前期の大規模邸宅の希少な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012305"},{"id":"00008422","register_sub_id":"101","register_pk":"134818","name":"村野家住宅穀蔵","kana":"むらのけじゅうたくこくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都東久留米市柳窪4-283","lat":35.74695313,"lng":139.49018671,"geo_status":"db","era":"江戸末期／江戸末期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、鉄板葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"13 － 0271","desc":"主屋の南西に位置する二階建土蔵。東西棟の置屋根で、切妻造妻入鉄板葺、桁行七・三メートル梁間四・六メートル。外壁は腰に四段の切石を張り、上部を漆喰仕上げとし、東面の開口にはに掛子塗の両開扉を吊る。内壁は板張。大谷石と白漆喰が清楚な外観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008422"},{"id":"00008419","register_sub_id":"101","register_pk":"134815","name":"村野家住宅主屋","kana":"むらのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都東久留米市柳窪4-283","lat":35.74722327,"lng":139.49013425,"geo_status":"db","era":"天保9年（1838）／安政4年（1857）増築・大正15年・昭和25年・昭和40年改修","year":1838,"year_source":"db","year_min":1838,"year_max":1838,"year_label":null,"structure":"木造平屋建、茅葺、建築面積274㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"13 － 0268","desc":"敷地中央に南面して建つ。東西棟の入母屋造茅葺、桁行二三メートル梁間一一メートル。東に土間や旧厩、西側に六間取を基本とする床上部を設け、トコや棚、付書院を構える座敷と次の間を西端に配す。大規模な農家建築で、落ち着きのある外観が屋敷林に融け込む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008419"},{"id":"00008423","register_sub_id":"101","register_pk":"134819","name":"村野家住宅新蔵","kana":"むらのけじゅうたくしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都東久留米市柳窪4-283","lat":35.74700558,"lng":139.49011589,"geo_status":"db","era":"明治28年／昭和32年・昭和62年改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積69㎡、蔵前及び茶室付","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"13 － 0272","desc":"主屋の西南、穀蔵の北側に建つ二階建土蔵。東西棟の切妻造妻入桟瓦葺、桁行七・三メートル梁間四・五メートル。東正面に蔵前を設け、その北側に茶室を配す。正面二階窓に掛子塗の両開扉を吊り、蔵前に下地窓を穿つ。木立のなか、穀蔵とともに清澄な趣を醸し出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008423"},{"id":"00008425","register_sub_id":"101","register_pk":"134821","name":"村野家住宅中雀門","kana":"むらのけじゅうたくちゅうじゃくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都東久留米市柳窪4-283","lat":35.74708951,"lng":139.49014212,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造、銅板葺、間口1.5m、塀付","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"13 － 0274","desc":"主屋と新蔵の間に板塀を設け、前庭と奥庭を画する。その中央に建つ一間の腕木門で、切妻造銅板葺。一・五メートルの間口に両開板戸を吊る。総欅造で、楣上に格子の欄間を入れ、一軒疎垂木。塀は下見板張で上部に漆喰壁を設ける。華奢で上品な意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008425"},{"id":"00008421","register_sub_id":"101","register_pk":"134817","name":"村野家住宅土蔵","kana":"むらのけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都東久留米市柳窪4-283","lat":35.74724425,"lng":139.49001623,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、鉄板葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"13 － 0270","desc":"主屋の北側に位置する。土蔵造二階建、東西棟の切妻造妻入鉄板葺、桁行五・四メートル梁間三・六メートル。内部は細かく柱を建て、板壁とし、柱間に鉄棒をたてるなど、厳重な仕様になる。外壁は漆喰仕上げで、東妻拝み部分に家紋を戴く。主屋と好対照な外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008421"},{"id":"00008420","register_sub_id":"101","register_pk":"134816","name":"村野家住宅離れ","kana":"むらのけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都東久留米市柳窪4-283","lat":35.74707377,"lng":139.48991395,"geo_status":"db","era":"明治後期／大正後期移築・昭和25年・平成3年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、銅板葺、建築面積105㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"13 － 0269","desc":"主屋の西側に渡り廊下を介して建つ。木造平屋建、建築面積一〇五平方メートル。主棟を東西棟の入母屋造、鉄板葺とし、東側に切妻屋根を南へ突出させる。トコや棚、付書院を構える主座敷と次の間を東西に並べ、東南隅に洋間を設ける。付書院欄間の彫刻が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008420"},{"id":"00008424","register_sub_id":"101","register_pk":"134820","name":"村野家住宅薬医門","kana":"むらのけじゅうたくやくいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都東久留米市柳窪4-283","lat":35.74722851,"lng":139.49046996,"geo_status":"db","era":"明治14年","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造、銅板葺、間口2.6m、塀付","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"13 － 0273","desc":"主屋の南東に位置する。一間薬医門、切妻造銅板葺。間口二・六メートルと比較的規模が大きい。両側に板塀を付設し、東側に潜戸を設ける。本柱上、冠木で固め、男梁とその上部に梁を架け、笈形付大瓶束で棟を支持。二軒疎垂木。総欅造で、本格的なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008424"},{"id":"00009736","register_sub_id":"101","register_pk":"195565","name":"森田家住宅板塀","kana":"もりたけじゅうたくいたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都あきる野市小川字小仲633-1","lat":35.72098382,"lng":139.31612403,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、鉄板葺、延長19m","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0321","desc":"門西端から敷地南辺を折曲がりに西へのびる塀で、高さ約二・三メートル、延長一九メートルを測る。玉石積の基礎上に土台を伏せ、柱上部の腕木で軒桁を受け、屋根は鉄板葺とする。壁は竪板張目板打で黒色塗装する。正面の門や見世蔵とともに屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009736"},{"id":"00009734","register_sub_id":"101","register_pk":"195563","name":"森田家住宅御看経堂","kana":"もりたけじゅうたくおかんきんどう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都あきる野市小川字小仲633-1","lat":35.7212467,"lng":139.31607401,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、銅板葺、建築面積11㎡","structure_material":"土蔵造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0319","desc":"西蔵の後方に建つ持仏堂。土蔵造平屋建、宝形造、向拝付で、屋根は置屋根式の銅板葺として頂部に宝珠を戴く。外壁は上部漆喰塗で、腰を研出し仕上げとする。内部は手前が三畳の拝所で、後方を仏壇構えとして虹梁をかける。旧家に残る御看経堂として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009734"},{"id":"00009733","register_sub_id":"101","register_pk":"195562","name":"森田家住宅旧米蔵","kana":"もりたけじゅうたくきゅうこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都あきる野市小川字小仲633-4","lat":35.7214085,"lng":139.31628103,"geo_status":"db","era":"江戸末期／平成8改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積107㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0318","desc":"主屋の西側に南北棟で建つ。桁行一四・六メートル梁間七・三メートル、土蔵造二階建、切妻造、置屋根式の桟瓦葺である。外壁は中塗仕上げで、二階の格子付窓に、土戸片引きとする。内部は南北二室に区分され、小屋は登り梁形式である。大型の米蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009733"},{"id":"00009728","register_sub_id":"101","register_pk":"195557","name":"森田家住宅主屋","kana":"もりたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都あきる野市小川字小仲633-1","lat":35.72115152,"lng":139.31638096,"geo_status":"db","era":"江戸末期／昭和48頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺及び銅板葺、建築面積178㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0313","desc":"睦橋通りに面した敷地の中央に建ち、木造平屋建、入母屋造桟瓦葺である。正面に構える唐破風造の式台玄関は、正面を二重虹梁とする本格的な形式とする。床上部は前後二列に三室ずつを配し、軸部重厚で、座敷飾も洗練されている。雄大な構えの大型民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009728"},{"id":"00009732","register_sub_id":"101","register_pk":"195561","name":"森田家住宅西蔵","kana":"もりたけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都あきる野市小川字小仲633-1","lat":35.72116342,"lng":139.31609543,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0317","desc":"主屋の西方に東西棟で建ち、東妻を戸口とする。桁行七・三メートル梁間五・六メートル、土蔵造二階建、切妻造、置屋根式の桟瓦葺である。外壁漆喰塗で東面二階に庇付の小窓を穿ち、掛子塗戸を開く。小屋は登り梁形式とする。家財蔵として使用された土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009732"},{"id":"00009730","register_sub_id":"101","register_pk":"195559","name":"森田家住宅前の蔵","kana":"もりたけじゅうたくまえのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都あきる野市小川字小仲633-1","lat":35.72089692,"lng":139.31649518,"geo_status":"db","era":"嘉永5頃／昭和58移築","year":1852,"year_source":"db","year_min":1852,"year_max":1852,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0315","desc":"敷地の南東隅に建つ。桁行七・三メートル梁間五・四メートル、土蔵造二階建、切妻造、置屋根式の鉄板葺で西妻を戸口とする。外壁はモルタル吹付け仕上げで腰を洗出しとし、南面上下階に鳥居枠と土扉付の窓を並べる。見世蔵とともに風格ある屋敷構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009730"},{"id":"00009729","register_sub_id":"101","register_pk":"195558","name":"森田家住宅見世蔵","kana":"もりたけじゅうたくみせぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都あきる野市小川字小仲633-1","lat":35.72092309,"lng":139.3162953,"geo_status":"db","era":"嘉永5","year":1852,"year_source":"db","year_min":1852,"year_max":1852,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0314","desc":"敷地南寄りに東西棟で建つ。桁行九・一メートル梁間五・五メートル、土蔵造二階建、置屋根式の鉄板葺で、南北面を下屋とする。外壁は腰を洗出しとし、二階に格子窓を穿つ。一階西寄りを板敷のミセとし、道路側に揚戸をたてて開口する。店舗機能を備えた土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009729"},{"id":"00009731","register_sub_id":"101","register_pk":"195560","name":"森田家住宅味噌蔵","kana":"もりたけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都あきる野市小川字小仲633-1","lat":35.721004,"lng":139.31654039,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、鉄板葺、建築面積17㎡","structure_material":"土蔵造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0316","desc":"敷地の南東寄り、前の蔵の後方に南北棟で建つ。桁行四・七メートル梁間三・六メートル、土蔵造平屋建、切妻造、置屋根式の鉄板葺である。外壁は漆喰塗で西面の戸口に額縁を象り、小屋は和小屋を組む。近世の屋敷構えを伝える土蔵で、現在も食料品を貯蔵する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009731"},{"id":"00009735","register_sub_id":"101","register_pk":"195564","name":"森田家住宅門","kana":"もりたけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都あきる野市小川字小仲633-1","lat":35.72096592,"lng":139.31623344,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、銅板葺、間口2.7m、左右袖塀及び潜戸付","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0320","desc":"主屋正面に構える門で、見世蔵の西壁に接続し、西側には板塀をのばす。一間薬医門、切妻造銅板葺で、左右に袖塀を設け、東側に潜戸を開く。本柱や冠木、梁などにケヤキの良材を用いた間口の広い表門で、見世蔵や板塀とともに風格ある表構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009735"},{"id":"00011082","register_sub_id":"101","register_pk":"205189","name":"森博士の家","kana":"もりはかせのいえ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都文京区本駒込一丁目11-51","lat":35.726409,"lng":139.749772,"geo_status":"db","era":"昭和26／昭和43改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積91㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"13 - 0365","desc":"建築家清家清が設計した小住宅。西寄りに玄関、東寄りに台所等、間に居室を配して連続させる。簡素な材料と間取りの中に、建具を介した自由な空間構成と、整理された生活動線による機能美を有する。後に住宅設計で高い評価を受けた清家の初期の代表作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011082"},{"id":"00001497","register_sub_id":"101","register_pk":"102487","name":"守屋家住宅主屋","kana":"もりやけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都大田区大森北3-22-26","lat":35.5825,"lng":139.731445,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積224㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"13 － 0068","desc":"本２階建，中廊下型の和風住宅と，玄関脇に設けた洋風応接間からなる。良質の材を用いた丁寧な仕事になり，座敷飾りの意匠や建具の細工などに優れ，高度な大工技術が窺える。昭和初期における質の高い和洋折衷住宅であり保存状況も良好である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001497"},{"id":"00008828","register_sub_id":"101","register_pk":"162271","name":"柳澤家住宅主屋","kana":"やなぎさわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都世田谷区大原1-1176","lat":35.66844272,"lng":139.66192562,"geo_status":"db","era":"昭和26年／昭和54年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"13 － 0287","desc":"南側の庭園に面して大きく妻を見せ、深い庇を付設。東端に玄関、中央にホールとテラス、西端に四畳半と納戸を配する小規模な住宅。ホールは板敷で梁を現し、北面にトコやトコ脇を構え、東面に暖炉を飾る。伝統民家の構成を引用しつつ、近代的な印象でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008828"},{"id":"00005595","register_sub_id":"101","register_pk":"106583","name":"山﨑家住宅主屋","kana":"やまさきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都大田区西嶺町33-9","lat":35.58197207,"lng":139.67788761,"geo_status":"db","era":"明治10頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、茅葺、建築面積115㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"13 － 0209","desc":"敷地ほぼ中央に建ち，桁行７間半，梁間４間半の規模で，木造平屋建，寄棟造，茅葺とし，四周に瓦葺の下屋を廻す。西側は整形四間取の床上部とし，床の間，仏壇の裏を納戸とする古い形式とする。農家主屋として建てられた当初の外観を良く残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005595"},{"id":"00011655","register_sub_id":"101","register_pk":"210671","name":"山﨑家住宅主屋","kana":"やまさきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区小石川五丁目19-33他","lat":35.719345,"lng":139.738802,"geo_status":"db","era":"大正6年／昭和35年・同38年・同61年・平成18年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積149㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"13-0380","desc":"小石川台地に建つ。二階建の洋館に平屋建の和館がＬ字型に接続する。洋館二階喫煙室は天井と窓上の欄間ステンドグラスを星形にしたイスラム風のデザインでまとめる。玄関、階段踊場には意匠性の高いステンドグラスを取り入れるなど、大正期の住宅建築の優品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011655"},{"id":"00012302","register_sub_id":"101","register_pk":"531626","name":"山脇家住宅表門及び塀","kana":"やまわきけじゅうたくおもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区千駄木三丁目635-10","lat":35.72664722,"lng":139.76163333,"geo_status":"db","era":"大正14年頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"表門 木造、瓦葺、間口3.9m 塀 木造、瓦葺、総延長11.2m、雪隠・露地口及び腰掛待合付","structure_material":"表門 木造","registered":"2018.05.10(平成30.05.10)","register_no":"13-408","desc":"敷地東面を区切る門塀。目板瓦を葺く塀の南寄りに桟瓦葺の表門を開き、やや奥に引分戸を建込む。塀の外側は焼杉板張、内側は杉皮張として、数寄屋風意匠を施す。塀の庭側には雪隠や露地口、腰掛待合を付設し、茶室に至る落ち着いた露地空間を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012302"},{"id":"00012301","register_sub_id":"101","register_pk":"531625","name":"山脇家住宅主屋","kana":"やまわきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区千駄木三丁目635-10","lat":35.72663611,"lng":139.76148333,"geo_status":"db","era":"大正14年頃／昭和中期改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積179㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"13-407","desc":"団子坂上の住宅街にある、茶人山脇善五郎の住宅。低平な平屋建で、一畳台目の睡庵、八畳広間の追遠、四畳半の楓亭と、丸炉のある玄関寄付の趣の異なる四席の茶室や水屋、居室を機能的に配する。丸太普請の繊細な数寄屋風建築で、笛吹嘉一郎による初期の作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012301"},{"id":"00000636","register_sub_id":"101","register_pk":"101626","name":"弥生正緑館（渋谷家住宅洋館）主屋","kana":"やよいしょうろくかん（しぶたにけじゅうたくようかん）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都文京区弥生一丁目2-3","lat":35.7193732,"lng":139.76032701,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造２階建，鉄板葺，建築面積92㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0017","desc":"日本橋に店を構える毛織雑貨輸出商の居宅。根津神社の西側高台に建つ。階下洋間一室を基本とするが，崖地に沿って不整形な玄関部や洋間の隅切り，階上の張り出し等をもつ。外装等改装されているが，階上西面切妻のバージボードに建設年の時代的特徴を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000636"},{"id":"00000637","register_sub_id":"101","register_pk":"101627","name":"弥生正緑館（渋谷家住宅洋館）庭門","kana":"やよいしょうろくかん（しぶたにけじゅうたくようかん）にわもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都文京区弥生一丁目2-3","lat":35.71923694,"lng":139.76044125,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造棟門，銅板葺","structure_material":"木造棟門","registered":"1998.09.02(平成10.09.02)","register_no":"13 － 0018","desc":"かっては現在地の西方に位置した正門の奥脇と庭園との境に建っていた門。現在は，正門奥の正面寄りに移設されている。棟木にムクリ材を用い，銅板葺ムクリ屋根を架ける編笠門形式をとる。柱材と冠木材に古材を用いるなど趣味性に富んだ門となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000637"},{"id":"00002892","register_sub_id":"101","register_pk":"103882","name":"よし梅芳町亭","kana":"よしうめよしちょうてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都中央区日本橋人形町1-5-2","lat":35.68510584,"lng":139.78182062,"geo_status":"db","era":"昭和2頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積81㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"13 － 0132","desc":"震災復興期に建てられた木造総２階建の住宅で，桁行５間梁間４間半，切妻造，平入である。外壁はモルタル塗に変更されたが，内部は天井板や板欄間など化粧に上質の材を用い，床や下地窓など数寄屋風の意匠も整い，昭和初期の和風の水準をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002892"},{"id":"00001503","register_sub_id":"101","register_pk":"102493","name":"吉川家住宅主屋","kana":"よしかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都大田区田園調布4-21-16","lat":35.59637642,"lng":139.6620671,"geo_status":"db","era":"大正12～13","year":1923,"year_source":"converted","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積129㎡","structure_material":"木造平屋建","registered":"2000.02.15(平成12.02.15)","register_no":"13 － 0074","desc":"沿革不詳だが映画関係者が撮影用に建設したと伝え，建設後まもなく転売された。平屋建，下見板張の洋館で，居間を中心とする平面計画と，装飾的要素の少ない簡明なデザインに特色がある。一部に増築等の改変はあるが内外装，建具等当初の姿を良く残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001503"},{"id":"00011885","register_sub_id":"101","register_pk":"211135","name":"私の家（清家清自邸）","kana":"わたしのいえ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都大田区東雪谷三丁目519","lat":35.594003,"lng":139.691505,"geo_status":"db","era":"昭和29年／昭和52年増改築","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"鉄筋コンクリート造平屋建、金属板葺、建築面積51㎡、地下室付","structure_material":"鉄筋コンクリート造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"13-382","desc":"鉄筋コンクリート造の小住宅。限られた面積の中、床高を一五センチメートルとし、庭の広さを取り込んだ一室住居に家族が住まう構成。内部は平坦なスラブをハブマイヤートラスが支え、家具的な装置で空間を緩やかに分節する。戦後小住宅を代表する秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011885"},{"id":"00004214","register_sub_id":"101","register_pk":"105204","name":"渡辺家住宅主屋","kana":"わたなべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都三鷹市井の頭3-24-7","lat":35.69549388,"lng":139.58169646,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積118㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"13 － 0177","desc":"南及び東が接道する敷地の北西寄りに東面して建つ。南に庭を置く木造平屋建の中廊下型住宅で，屋根は切妻造，桟瓦葺とする。外壁は漆喰塗で，一部に下見板を用いる。建設当時の姿をよく留める。昭和初期井の頭地区における住宅地化を物語る建造物のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004214"},{"id":"00006418","register_sub_id":"101","register_pk":"107401","name":"渡辺家住宅主屋","kana":"わたなべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都三鷹市下連雀4-195","lat":35.69580424,"lng":139.56224178,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積160㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"13 － 0221","desc":"閑静な住宅地の、通り西側に建つ木造平屋建。棟の高い入母屋造妻入桟瓦葺で、正面南寄りに庇付切妻造屋根の玄関を付け、意匠性の高い正面を造る。玄関奥に天井の高い茶の間と客間、その南に広縁を設ける。トコ構えや繊細な細工になる付書院など見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006418"},{"id":"00011270","register_sub_id":"101","register_pk":"209106","name":"渡邊家住宅主屋","kana":"わたなべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都杉並区荻窪四丁目252-1","lat":35.701465,"lng":139.623529,"geo_status":"db","era":"昭和34／昭和45頃・同55頃・平成26改修","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積193㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"13－0368","desc":"「荻窪の家」として知られる吉村順三設計の住宅。くの字型平面の木造平屋建で、西に玄関、居間、台所を配し、東は中廊下を通して南面に居室、北側に水周り等を配する。緩やかな片流屋根の背面に一段下げて下屋をかけ、高窓を設ける。戦後モダニズム住宅の秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011270"},{"id":"00012712","register_sub_id":"101","register_pk":"367615","name":"和朗フラット四号館","kana":"わろうふらっとよんごうかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":null,"lat":null,"lng":null,"geo_status":"missing","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、スレート葺、建築面積140㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"13 － 416","desc":"麻布台の住宅地にある賃貸アパート。木造二階建、南北棟の切妻造で路地に東面して建つ。各階に四戸を設け、住戸毎に間取や仕上を異にする。正面は出窓やアルコーブを変則的に配し、印象的な路地景観を形成する。開発著しい都心部に残る貴重な戦前の都市住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012712"},{"id":"00005263","register_sub_id":"101","register_pk":"106251","name":"愛光商会吉浜寮","kana":"あいこうしょうかいよしはまりょう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町吉浜字柏坂1","lat":35.15085986,"lng":139.12261258,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造3階建、鉄板葺、建築面積137㎡","structure_material":"木造3階建","registered":"2006.03.02(平成18.03.02)","register_no":"14 － 0121","desc":"南辺を接道する敷地に南面して東西棟で建つ。桁行１１ｍ，梁間９ｍの規模で，木造３階建，切妻造，鉄板葺で，妻壁をうだつ状に立ち上げる。外壁をモルタル塗の大壁とするが，２階，３階正面は持ち送りで柱形を前に出し，上げ下げ窓を連続して配する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005263"},{"id":"00015163","register_sub_id":"101","register_pk":"530587","name":"穴澤家住宅座敷蔵","kana":"あなざわけじゅうたくざしきぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横須賀市西浦賀一丁目32-1","lat":35.24207222,"lng":139.71812222,"geo_status":"db","era":"大正5年／昭和63年頃・平成27年改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木骨石造2階建、瓦葺、建築面積77㎡","structure_material":"木骨石造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"14 - 0359","desc":"浦賀港西岸に位置し、通りに東面する、旧商家の座敷蔵。桁行八・六メートル、梁間五・八メートル、凝灰岩を馬乗り目地で積んだ木骨石造二階建切妻造平入で正面全幅に深い下屋を張出す。二階座敷は吟味した良材で造作。近代浦賀の繁栄を物語る貴重な座敷蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015163"},{"id":"00012721","register_sub_id":"101","register_pk":"367624","name":"有田家住宅主屋","kana":"ありたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市大鋸三丁目139-2他","lat":35.34954722,"lng":139.49049444,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積98㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"14 － 0266","desc":"旧東海道遊行寺坂東側の丘上に南面して建つ。当地の農家に珍しい妻入で、寄棟造桟瓦葺の周囲に下屋を廻し、正面東半の玄関回りに太い柱を用いる。田字形平面で、玄関を矩折の土間とする点は藤沢宿の町家に通じる。近代の藤沢宿周縁の様相を伝える民家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012721"},{"id":"00012722","register_sub_id":"101","register_pk":"367625","name":"有田家住宅土蔵","kana":"ありたけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県藤沢市大鋸三丁目139-2他","lat":35.34941389,"lng":139.49046667,"geo_status":"db","era":"大正12年／昭和2年増築","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造2階建、金属板葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"14 － 0267","desc":"主屋の南側に南北棟で建つ家財蔵。置屋根式の土蔵造二階建で、西面に下屋を出して戸口を設け、東面に味噌蔵を張出す。外壁は漆喰塗の腰下見板張で、軒に鉢巻を廻す。二階の南面と西面に設けた土戸付の窓に繰形付の側板を飾る庇を付すなど丁寧な造作をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012722"},{"id":"00011487","register_sub_id":"101","register_pk":"210382","name":"イエズス孝女会修道院旧館（旧東伏見宮葉山別邸）","kana":"いえずすこうじょかいしゅうどういんきゅうかん（きゅうひがしふしみのみやはやまべってい）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県三浦郡葉山町堀内字牛ケ谷1968","lat":35.27325694,"lng":139.58126389,"geo_status":"db","era":"大正3年／昭和51年・同62年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、銅板葺、建築面積280㎡、塔屋付","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"14-0228","desc":"旧東伏見宮葉山別邸の洋館で設計は木子幸三郎。玄関ポーチと搭屋を設け外壁下見板張で細部にセセッションを用いる。一・二階の西側に広いサンルームを設け、二階に宮家特有の高さのある和室ももつ。内外とも気品を備えた意匠で、海浜の別邸らしく開放的な構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011487"},{"id":"00007460","register_sub_id":"101","register_pk":"108442","name":"岩瀬家住宅主屋","kana":"いわせけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県小田原市鴨宮字宝町692","lat":35.27915517,"lng":139.17647421,"geo_status":"db","era":"安政5頃／昭和40頃・平成19改修","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"木造平屋建、茅葺、建築面積190㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"14 － 0147","desc":"酒匂川東岸の水田地帯であった敷地の中央に南面して建つ。桁行１９ｍ梁間９．１ｍの木造平屋建。寄棟造茅葺で、出桁造で深い軒を造り、土間前面には絵様繰形付の持送りを付ける。東寄りが土間で、床上は食違い六間取とする。当地方における上層農家の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007460"},{"id":"00005770","register_sub_id":"101","register_pk":"106758","name":"遠藤家住宅衣装蔵","kana":"えんどうけじゅうたくいしょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県相模原市緑区澤井字中里東583-1","lat":35.62607074,"lng":139.14999387,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"土蔵造2階建、鉄板葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"14 － 0131","desc":"主屋西方に建つ。桁行６ｍ，梁間４ｍ，土蔵造２階建，切妻造，鉄板葺で，正面に下屋庇を設ける。外部は腰下を石積風モルタル洗い出し，上部は漆喰塗で水切り２段とする。扉廻りの漆喰仕上げは入念で，主屋前面にあって穀蔵と対をなし，敷地景観上重要である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005770"},{"id":"00005777","register_sub_id":"101","register_pk":"106765","name":"遠藤家住宅穀蔵","kana":"えんどうけじゅうたくこくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県相模原市緑区澤井字中里東583-1","lat":35.62596635,"lng":139.15023535,"geo_status":"db","era":"文化7","year":1810,"year_source":"db","year_min":1810,"year_max":1810,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"14 － 0132","desc":"主屋の東南方に建つ。桁行５ｍ，梁間３．５ｍ，土蔵造２階建，切妻造，鉄板葺。西側に下屋を附属し，味噌蔵とする。外部は腰下をモルタル洗い出しとし，上部は漆喰仕上げ，屋根は置屋根とする。主屋の道路側に立地し，大規模農家の屋敷景観を構成し貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005777"},{"id":"00005769","register_sub_id":"101","register_pk":"106757","name":"遠藤家住宅主屋","kana":"えんどうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県相模原市緑区澤井字中里東583-1","lat":35.62612987,"lng":139.15012261,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階一部3階建、鉄板葺、建築面積184㎡","structure_material":"木造2階一部3階建","registered":"2006.10.18(平成18.10.18)","register_no":"14 － 0130","desc":"敷地中央に南西面して建つ。桁行１６ｍ，梁間１０ｍ，木造２階建，一部３階，切妻造，鉄板葺。２階正面軒をせがい造とする。床の間付の座敷をもつ鍵座敷型民家。養蚕事業の拡充に伴う作業空間の拡大の傾向をよく留めており，当地の民家の発展形態を知る上で貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005769"},{"id":"00007983","register_sub_id":"101","register_pk":"128815","name":"尾崎家住宅四阿","kana":"おざきけじゅうたくあづまや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字入谷261-38","lat":35.14448875,"lng":139.08110829,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.2㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"14-0159","desc":"敷地の南西隅、庭園内に建つ。小規模な木造平屋建で、入母屋造銅板葺。西面に腰掛を備えた吹放ち、柱を磨丸太、垂木を赤松の小丸太とし、天井や軒は二種の網代を使い分ける。ひしゃぎ竹の腰壁で、扇形と円形の開口を穿つ。庭園と調和のとれた瀟洒な建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007983"},{"id":"00007981","register_sub_id":"101","register_pk":"128813","name":"尾崎家住宅主屋","kana":"おざきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字入谷261-38","lat":35.14465593,"lng":139.08124941,"geo_status":"db","era":"昭和16／昭和25・昭和27増築","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積165㎡","structure_material":"木造平屋一部2階建","registered":"2010.01.15(平成22.01.15)","register_no":"14-0157","desc":"南斜面の別荘地内の、東西に長い敷地に建つ。木造平屋一部２階建、桟瓦葺、建築面積１６５㎡。次の間付の客間を中心に西に玄関と茶室、台所、東に寝室などを配し、凝った意匠の室内空間をつくる。外観は切妻造に入母屋や寄棟屋根を組み合わせ、複雑で変化に富む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007981"},{"id":"00007984","register_sub_id":"101","register_pk":"128816","name":"尾崎家住宅門","kana":"おざきけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字入谷261-38","lat":35.14454086,"lng":139.08114302,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造、銅板葺、間口1.6m","structure_material":"木造","registered":"2010.01.15(平成22.01.15)","register_no":"14-0160","desc":"主屋の西南、西側道路から少し入った位置に建つ腕木門。南北棟の切妻造銅板葺、間口１．６ｍに引違い戸をたて、両脇に袖壁を付ける。柱と桁は皮付丸太で、小丸太の垂木を一部吹寄せにする。両脇壁は腰に女竹を密に張る漆喰仕上げで、蔦葉形に穿つ。軽快な門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007984"},{"id":"00007982","register_sub_id":"101","register_pk":"128814","name":"尾崎家住宅浴室","kana":"おざきけじゅうたくよくしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡湯河原町宮上字入谷261-38","lat":35.14453869,"lng":139.08147738,"geo_status":"db","era":"昭和16／昭和25増築","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、鉄板一部銅板葺、建築面積14㎡、地下通路付","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"14-0158","desc":"主屋の南東に建ち、地下通路で接続。木造平屋建、東西棟の切妻造で、西面に庇を付け、銅及び鉄板葺、建築面積１４㎡。脱衣室と湯浴室からなり、杉皮張の外壁や皮付丸太の棹縁天井など、小規模ながら趣のある意匠で、温泉地に建つ別荘にふさわしい佇まいをもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007982"},{"id":"00006086","register_sub_id":"101","register_pk":"107071","name":"小澤家住宅表門","kana":"おざわけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県伊勢原市西富岡370","lat":35.41782386,"lng":139.3031951,"geo_status":"db","era":"江戸末期／明治20頃移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.7m、塀延長9.1m付","structure_material":"木造","registered":"2007.05.15(平成19.05.15)","register_no":"14 － 0140","desc":"一間一戸薬医門，軒は一軒半繁垂木で，切妻造，桟瓦葺とする。装飾は控えるが，当初の朱塗が僅かに残り，絵様繰形のある女梁や笈形付の大瓶束，控柱間の頭貫先端の木鼻等，要所を飾り，優秀な技術を見せる。旧平塚宿本陣の表門で，宿場における唯一の建築遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006086"},{"id":"00006085","register_sub_id":"101","register_pk":"107070","name":"小澤家住宅主屋","kana":"おざわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県伊勢原市西富岡370","lat":35.41805855,"lng":139.3033171,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積260㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"14 － 0139","desc":"敷地の中央北寄りに位置し，南面して建つ。桁行１１間，梁間７間規模，木造平屋建，寄棟造，茅葺（鉄板仮葺）の大規模農家。東半に土間，西半に２０畳間，８畳の座敷等４室を配する。柱や差物，梁は木太く，建具や床の間まわりの造作は優秀で，細工も精緻。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006085"},{"id":"00006098","register_sub_id":"101","register_pk":"107083","name":"小澤家住宅庭塀","kana":"おざわけじゅうたくにわべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県伊勢原市西富岡370","lat":35.41801406,"lng":139.30318969,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"練塀、瓦葺、延長11m","structure_material":"練塀","registered":"2007.05.15(平成19.05.15)","register_no":"14 － 0141","desc":"主屋南面の戸袋辺りから南方に延べ３．７ｍ，矩に折れて西方に７．１ｍ延び，座敷前の庭と主屋出入口前の空間を区分する。高さ１．６ｍで，桟瓦葺の屋根を載せる。壁は瓦を積んだ練塀で，瓦小口を並べて見せた重厚なつくりとし，敷地景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006098"},{"id":"00001771","register_sub_id":"101","register_pk":"102761","name":"小田原文学館（旧田中光顕別邸）別館","kana":"おだわらぶんがくかん（きゅうたなかみつあきべってい）べっかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県小田原市南町2-3-18","lat":35.24419479,"lng":139.15359428,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、銅板葺、建築面積245㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"14 － 0043","desc":"昭和前期まで活躍した政治家田中光顕の別邸で，白秋童謡館として活用。木造２階建，１部地階付，正面右に玄関を設ける。屋根は入母屋造・瓦棒銅板葺で，各階に銅板庇を廻す。内部は開放的な数寄屋風の意匠で，玄関奧には洋室をもち，近代の別邸建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001771"},{"id":"00001770","register_sub_id":"101","register_pk":"102760","name":"小田原文学館（旧田中光顕別邸）本館","kana":"おだわらぶんがくかん（きゅうたなかみつあきべってい）ほんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県小田原市南町2-3-4","lat":35.2447828,"lng":139.153717,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造3階建、瓦葺、建築面積361㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2000.09.26(平成12.09.26)","register_no":"14 － 0042","desc":"宮内大臣などを務めた政治家田中光顕の別邸で，展示施設として活用。ＲＣ造３階建の本館部と木造平屋建の管理棟からなる。本館はスパニッシュ瓦葺，東南隅のサンルーム，３階のベランダやパーゴラ等がモダニズムの特徴を示し，近代別荘地の景観を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001770"},{"id":"00012135","register_sub_id":"101","register_pk":"352934","name":"尾日向家住宅洋館・和館","kana":"おびなたけじゅうたくようかん・わかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市鵠沼松が岡一丁目7393-1","lat":35.319608,"lng":139.479635,"geo_status":"db","era":"昭和3年頃／昭和40年・同60年増築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積224㎡","structure_material":"木造平屋一部2階建","registered":"2018.03.27(平成30.03.27)","register_no":"14-254","desc":"南北棟平屋建の洋館と和館の間を二階建の洋館でつなぐ。洋館外壁は腰スクラッチタイル貼、上部モルタル塗とし、屋根は赤褐色の洋瓦を葺く。寄木張の床に腰壁板張で暖炉を備える洋館の応接室、和館の一〇畳座敷など、意匠的にも意を凝らした大規模住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012135"},{"id":"00007733","register_sub_id":"101","register_pk":"108715","name":"かいひん荘鎌倉洋館（旧村田家住宅洋館）","kana":"かいひんそうかまくらようかん（きゅうむらたけじゅうたくようかん）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県鎌倉市由比ガ浜4-1185-2","lat":35.31190389,"lng":139.54150431,"geo_status":"db","era":"大正13／昭和49頃・昭和57改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、スレート葺一部銅板葺、建築面積70㎡","structure_material":"木造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"14-0154","desc":"由比ガ浜の北方の住宅地に所在する。建築面積７０㎡、木造２階建の洋館で、東西棟の腰折屋根に円弧状の突出部やベイウィンドゥを付け、変化に富む外観をつくる。スレート葺一部銅板葺。東妻や天井の中心飾り、内壁の上部などに良質のレリーフが残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007733"},{"id":"00005779","register_sub_id":"101","register_pk":"106767","name":"鎌倉市長谷子ども会館蔵","kana":"かまくらしはせこどもかいかんくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県鎌倉市長谷1-227-32","lat":35.31420408,"lng":139.53784026,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"14 － 0123","desc":"洋館北側に接続する。木造平屋建，切妻造，桟瓦葺。外壁を下見板張とし，窓，窓枠などともに洋風の意匠とする。青色に塗られた外観が特徴的で，室内は吹き抜けとして高い内部空間を確保する。洋館との統一感を考慮して，洋風の意匠を基調としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005779"},{"id":"00005767","register_sub_id":"101","register_pk":"106755","name":"鎌倉市長谷子ども会館洋館","kana":"かまくらしはせこどもかいかんようかん","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県鎌倉市長谷1-227-32","lat":35.31412694,"lng":139.53786624,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、スレート葺、建築面積73㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"14 － 0122","desc":"敷地中央に南面して建つ。木造２階建，寄棟造，スレート葺。両隅を円弧にした特徴的なバルコニーを円柱で支え，フリーズや柱頭，鋳鉄製手摺，開口部の額縁などに優美な装飾を施す。内部も階段手摺や天井飾りなどに技巧を凝らし，全体に華麗な造形意匠をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005767"},{"id":"00011658","register_sub_id":"101","register_pk":"210674","name":"鎌倉市吉屋信子記念館主屋","kana":"かまくらしよしやのぶこきねんかんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県鎌倉市長谷一丁目194-21","lat":35.314899,"lng":139.540809,"geo_status":"db","era":"昭和37年","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"木造一部コンクリートブロック造平屋建、スレート葺、建築面積213㎡","structure_material":"木造一部コンクリートブロック造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"14-0230","desc":"作家の住宅。木造平屋建で、背面西にはコンクリートブロック造倉庫が付属する。玄関から居間・食堂、書斎、寝室と連なる平面、内法材を減らし床レベルに工夫を凝らす点など、和風要素を巧みに取り入れた吉田五十八による数寄屋住宅の特徴をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011658"},{"id":"00011659","register_sub_id":"101","register_pk":"210675","name":"鎌倉市吉屋信子記念館門及び塀","kana":"かまくらしよしやのぶこきねんかんもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県鎌倉市長谷一丁目194-21","lat":35.314537,"lng":139.54102,"geo_status":"db","era":"昭和37年頃","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"門 木造、瓦葺、間口1.8m 塀 木造、瓦葺、延長29m","structure_material":"門 木造","registered":"2017.06.28(平成29.06.28)","register_no":"14-0231","desc":"敷地南端を画す。東寄りに配す門は磨丸太を柱に用いる桟瓦葺の腕木門で、垂木に丸太と竹を交互に配し、化粧野地は檜皮とする。左右に伸びる塀は高い石積の基壇上に腰板・土壁とし、桟瓦を葺く。特色ある意匠で、地域の景観を特徴付けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011659"},{"id":"00001663","register_sub_id":"101","register_pk":"102653","name":"鎌倉文学館本館","kana":"かまくらぶんがくかんほんかん","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市長谷1-215","lat":35.31556311,"lng":139.53891166,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木及び鉄筋コンクリート造3階建、瓦葺、建築面積462㎡","structure_material":"木及び鉄筋コンクリート造3階建","registered":"2000.04.28(平成12.04.28)","register_no":"14 － 0041","desc":"もと加賀前田家鎌倉別邸で、三方を山に囲われ、南へ広く開けて鎌倉の海を見下ろす広大な敷地に建つ。１階鉄筋コンクリート造、２階３階木造のハーフティンバーとスパニッシュを基調とした邸宅建築。設計は前田家建築係の渡辺栄治、施工は竹中工務店。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001663"},{"id":"00014579","register_sub_id":"101","register_pk":"515121","name":"河合家住宅（旧横浜市営外国人住宅）主屋","kana":"かわいけじゅうたく（きゅうよこはましえいがいこくじんじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市中区山手町124","lat":35.43526667,"lng":139.65494167,"geo_status":"db","era":"昭和4年／同39年頃・平成26年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"14 - 0328","desc":"旧山手居留地の南部丘陵に所在する洋風住宅で、関東大震災後に横浜市が建築した外国人住宅。切妻造平屋建、角屋部分半切妻造。柱頭飾り付円柱の玄関ポーチが特徴的。内部は居間中心の平面で、居間と食堂に暖炉を備える。震災復興の公営外国人住宅として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014579"},{"id":"00010429","register_sub_id":"101","register_pk":"199388","name":"環山","kana":"かんざん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡箱根町木賀字新田952-4","lat":35.250065,"lng":139.052552,"geo_status":"db","era":"昭和初期／昭和56・平成24改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、茅葺一部瓦葺、建築面積172㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"14 － 0193","desc":"入母屋造茅葺の広間棟と寄棟造茅葺の茶室棟を繋げた独特な構成で、広間棟は表千家残月を写した主室と次の間に縁を廻らし、茶室棟は三畳半茶室と大炉の間、立礼席からなり多様な数寄屋意匠でまとめる。箱根に残る戦前の財界人の数寄屋別荘としても価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010429"},{"id":"00016365","register_sub_id":"101","register_pk":"536432","name":"観山亭主屋","kana":"かんざんていおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅字強羅1300-85","lat":35.24815,"lng":139.04301111,"geo_status":"db","era":"昭和21年／昭和25年増築、平成10年改修","year":1946,"year_source":"db","year_min":1946,"year_max":1946,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"14 - 0365","desc":"名勝神仙郷の創設者岡田茂吉の住宅主屋。敷地中央西寄りに建ち、玄関・座敷・仏間の北に吉田五十八設計で寝室及び書斎を増築。こけら葺の緩勾配屋根と下屋が庭園と調和する。岡田の生活の様相を伝え、三面を開口とする書斎など増築部は吉田作品としても貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016365"},{"id":"00016366","register_sub_id":"101","register_pk":"536433","name":"観山亭湯殿","kana":"かんざんていゆどの","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"神奈川県","address":"神奈川県足柄下郡箱根町強羅字強羅1300-85","lat":35.24815278,"lng":139.04286111,"geo_status":"db","era":"昭和22年","year":1947,"year_source":"db","year_min":1947,"year_max":1947,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"14 - 0366","desc":"観山亭の西に位置する浴室棟。東から化粧室・脱衣室・浴室を配し、屋根こけら葺で棟高を変える。化粧室は畳敷で庭側に開口を開け、浴室は床中央を木煉瓦敷とし、大理石の浴槽を据える。庭に面した開放的なつくりの浴室棟で、吉田五十八による秀作の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016366"},{"id":"00005768","register_sub_id":"101","register_pk":"106756","name":"神原家住宅長屋門","kana":"かんばらけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県相模原市緑区牧野4204","lat":35.58252635,"lng":139.15214265,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（銅板仮葺）、建築面積86㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"14 － 0129","desc":"敷地入口に東面して建つ。桁行９間，梁間２間，木造，入母屋造，茅葺（銅板仮葺）。正背面は上屋梁を伸ばして軒桁を受け，深いせがい造とする。中央３間を通路として扉を開き，両脇に部屋を設ける。軒や小屋組に当初形式を良く留め，豪壮な屋敷構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005768"},{"id":"00013240","register_sub_id":"101","register_pk":"366229","name":"旧芦川家住宅主屋（緑水庵）","kana":"きゅうあしかわけじゅうたくおもや（りょくすいあん）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県秦野市蓑毛字中里269-2","lat":35.41008611,"lng":139.23132222,"geo_status":"db","era":"昭和5年頃／平成3年移築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、茅葺（金属板仮葺）、建築面積126㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"14 － 0281","desc":"市街南部から移築した民家で、桁行八間規模の寄棟造茅葺金属板仮葺である。床上部は整形四間取で県内民家の基本形をとるが、正面軒で出桁と登梁を併用する架構や、良質な竹を産した当地らしく外壁を割竹張とする手法などに、地域的特色をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013240"},{"id":"00014342","register_sub_id":"101","register_pk":"511331","name":"旧足立家別邸主屋","kana":"きゅうあだちけべっていおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県三浦郡葉山町堀内字牛ヶ谷2019","lat":35.27290833,"lng":139.58218333,"geo_status":"db","era":"昭和8年／令和2年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積182㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0320","desc":"葉山町西部の山裾に位置する実業家の別邸で、設計は佐藤功一。二階建切妻造桟瓦葺で南面し、外壁はハーフティンバー。内部は中廊下を通して和洋の部屋を巧みに配し、内装材には王子製紙製繊維板のトマテックスを多用する。佐藤功一の作品としても貴重な住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014342"},{"id":"00014765","register_sub_id":"101","register_pk":"519023","name":"旧石田家国府津別邸主屋","kana":"きゅういしだけこうづべっていおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県小田原市国府津字隆限地2064-3","lat":35.28845,"lng":139.2072,"geo_status":"db","era":"大正13年／昭和50年頃改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積136㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0333","desc":"相模湾を南に望む丘陵西麓に南面して建つ別荘の主屋。東西棟の座敷棟と厨房棟を雁行させた平屋建で東に洋館が接続。座敷棟は西妻を玄関として入母屋屋根を重ね、内部は東西三室で、東室を数寄屋風の座敷とし、床など自由な造形をみせる上質な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014765"},{"id":"00014766","register_sub_id":"101","register_pk":"519024","name":"旧石田家国府津別邸洋館","kana":"きゅういしだけこうづべっていようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県小田原市国府津字隆限地2064-3","lat":35.28841667,"lng":139.20734722,"geo_status":"db","era":"昭和16年","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0334","desc":"主屋の座敷棟の東側に接続する切妻造スレート葺の洋館。外壁は腰を鉄平石貼、内法壁を横板張、妻壁を円弧基調のハーフティンバーとする。内部は一室の板敷とし、北東隅に暖炉を築き、背後に石貼の煙突を立てる。瀟洒な山小屋風の建物で戦前の別荘建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014766"}];
